function toast(message) {
    const el = $("#toast");
    el.textContent = message;
    el.hidden = false;
    clearTimeout(toast.timer);
    toast.timer = setTimeout(() => { el.hidden = true; }, 2600);
}
function api(path, options) {
    return apiRequest(path, options).catch((error) => {
        if (error instanceof ApiError && error.status === 401) location.href = "/pages/login.html";
        else toast(error instanceof ApiError ? error.message : "Não foi possível concluir a operação.");
        throw error;
    });
}
async function uploadFile(file, kind="image") {
    if (!(file instanceof File) || !file.size) return "";
    const response = await fetch("/api/upload", {
        method:"POST", credentials:"same-origin", body:file,
        headers:{"Content-Type":file.type,"X-Upload-Kind":kind,"X-File-Name":encodeURIComponent(file.name)}
    });
    const data = await response.json().catch(()=>null);
    if(!response.ok) throw new ApiError(data?.message||"Falha no upload.",response.status,data);
    return data.url;
}

function roleLabel(role) { return ({owner:"Dono",master:"Mestre","co-master":"Co-Mestre",player:"Jogador",spectator:"Espectador"})[role] ?? role; }
function resultLabel(type) { return ({success:"Sucesso",failure:"Falha",critical:"Crítico",messy_critical:"Crítico Bestial",bestial_failure:"Falha Bestial"})[type] ?? type; }
function timeLabel(raw) { if(!raw)return ""; const d=new Date(raw.includes("T")?raw:raw.replace(" ","T")+"Z"); return Number.isNaN(d.getTime())?raw:new Intl.DateTimeFormat("pt-BR",{hour:"2-digit",minute:"2-digit"}).format(d); }
function canSeeMaster() { return state.canManage && !state.playerView; }
function updateMasterVisibility() { $$(".master-only").forEach(el => { el.hidden = !state.canManage; }); document.body.classList.toggle("player-simulation", state.playerView); }

async function loadBootstrap({keepScene=true}={}) {
    const data = await api(`/api/vtt/chronicles/${chronicleId}/bootstrap`);
    const previous = keepScene ? state.scene?.id : null;
    Object.assign(state, {
        me:data.me, chronicle:data.chronicle, role:data.role, canManage:data.canManage, permissions:data.permissions,
        scenes:data.scenes, folders:data.folders, members:data.members, characters:data.characters, npcs:data.npcs,
        items:data.items, journals:data.journals, tables:data.tables, decks:data.decks, macros:data.macros, media:data.media, cutscenes:data.cutscenes||[],
        encounters:data.encounters, world:data.world, rolls:data.rolls
    });
    if(!state.lastRollId && data.rolls?.length) state.lastRollId=Math.max(...data.rolls.map(r=>Number(r.id)||0));
    $("#chronicle-name").textContent = `${data.chronicle.name} · ${roleLabel(data.role)}`;
    $("#back-to-chronicle").href = `/pages/cronica.html?id=${chronicleId}`;
    updateMasterVisibility();
    renderSceneNavigation(); renderDirectories(); renderHotbar(); renderOnline(); renderSettings(); fillDiceCharacters();
    const desired = data.scenes.find(s=>s.id===previous) || data.scenes.find(s=>s.is_current) || data.scenes[0];
    if (desired && (!state.scene || desired.id !== state.scene.id)) await openScene(desired.id, {fit:true});
    if (!desired) clearScene();
    applyPause();
}

async function openScene(sceneId, {fit=false}={}) {
    const data = await api(`/api/vtt/scenes/${sceneId}`);
    state.scene = data.scene;
    state.objects = data.objects;
    state.fog = data.fog;
    state.pings = data.pings;
    state.selected = null; state.selectedTokens.clear();
    renderScene(); renderSceneNavigation(); renderSceneDirectory(); renderInspector(); renderToolOptions();
    if (fit) fitScene(); else applyStageTransform();
    updateAmbientSounds();
}

function clearScene() {
    state.scene = null;
    $("#scene-empty").hidden = false;
    $("#viewport").hidden = true;
    $("#active-scene-label").textContent = "SEM CENA";
    for (const id of ["token-layer","tile-under-layer","tile-over-layer","region-layer","note-layer","door-layer","gm-layer","ping-layer","cursor-layer"]) $(`#${id}`).innerHTML="";
    $("#drawing-layer").innerHTML=""; $("#wall-layer").innerHTML=""; $("#measure-layer").innerHTML="";
}

function renderScene() {
    const scene = state.scene;
    if (!scene) return clearScene();
    $("#scene-empty").hidden = true;
    $("#viewport").hidden = false;
    const stage=$("#stage"); stage.style.width=`${scene.width}px`; stage.style.height=`${scene.height}px`;
    const bg=$("#scene-background"); bg.style.backgroundColor=scene.background_color||"#09090b"; bg.style.backgroundImage=scene.image_url?`url("${scene.image_url.replaceAll('"','%22')}")`:"none";
    const foreground=$("#scene-foreground"); if(foreground) foreground.style.backgroundImage=scene.foreground_url?`url("${String(scene.foreground_url).replaceAll('"','%22')}")`:"none";
    const grid=$("#grid-layer"); grid.className=`grid-layer ${scene.grid_type||"square"}`; grid.style.setProperty("--grid-size",`${scene.grid_size}px`); grid.style.backgroundSize=scene.grid_type==="square"?`${scene.grid_size}px ${scene.grid_size}px`:""; grid.hidden=scene.grid_type==="gridless";
    $("#lighting-layer").width=scene.width; $("#lighting-layer").height=scene.height; $("#fog-layer").width=scene.width; $("#fog-layer").height=scene.height;
    [$("#drawing-layer"),$("#wall-layer"),$("#measure-layer")].forEach(svg=>{svg.setAttribute("viewBox",`0 0 ${scene.width} ${scene.height}`)});
    $("#active-scene-label").textContent = scene.title.toUpperCase();
    renderTiles(); renderDrawings(); renderRegions(); renderTokens(); renderWalls(); renderNotes(); renderGmMarkers(); renderWeather(); renderPings(); renderLighting(); renderFog();
}

function renderSceneNavigation() {
    const nav=$("#scene-nav");
    nav.innerHTML = state.scenes.filter(s=>state.canManage || s.nav_visible).map(scene=>`<button class="scene-tab ${state.scene?.id===scene.id?'active':''}" data-scene-id="${scene.id}" title="${escapeHtml(scene.title)}"><span class="scene-thumb" style="background-image:${scene.image_url?`url('${escapeHtml(scene.image_url)}')`:"none"}"></span>${scene.is_current?'<i></i>':''}<span>${escapeHtml(scene.title)}</span></button>`).join("");
    $$(".scene-tab",nav).forEach(btn=>btn.addEventListener("click",()=>openScene(Number(btn.dataset.sceneId),{fit:true})));
}

function renderTiles() {
    const under=$("#tile-under-layer"),over=$("#tile-over-layer"); under.innerHTML="";over.innerHTML="";
    for(const tile of state.objects.tiles){
        const el=document.createElement("div"); el.className=`tile ${tile.layer==='gm'?'gm':''} ${state.selected?.type==='tiles'&&state.selected.id===tile.id?'selected':''}`; el.dataset.objectType="tiles"; el.dataset.objectId=tile.id;
        Object.assign(el.style,{left:`${tile.x}px`,top:`${tile.y}px`,width:`${tile.width}px`,height:`${tile.height}px`,transform:`rotate(${tile.rotation}deg)`,opacity:String(tile.opacity),backgroundImage:`url("${String(tile.image_url).replaceAll('"','%22')}")`});
        bindObject(el,"tiles",tile); (tile.layer==='over'?over:under).append(el);
    }
}
function renderDrawings() {
    const svg=$("#drawing-layer"); svg.innerHTML="";
    for(const d of state.objects.drawings){
        let node;
        if(d.drawing_type==="freehand") { node=document.createElementNS("http://www.w3.org/2000/svg","polyline"); node.setAttribute("points",(d.points||[]).map(p=>`${p.x},${p.y}`).join(" ")); node.setAttribute("fill","none"); }
        else if(d.drawing_type==="ellipse"){node=document.createElementNS("http://www.w3.org/2000/svg","ellipse");node.setAttribute("cx",d.x+d.width/2);node.setAttribute("cy",d.y+d.height/2);node.setAttribute("rx",Math.abs(d.width/2));node.setAttribute("ry",Math.abs(d.height/2));node.setAttribute("fill",d.fill||"transparent");}
        else if(d.drawing_type==="text"){node=document.createElementNS("http://www.w3.org/2000/svg","text");node.setAttribute("x",d.x);node.setAttribute("y",d.y);node.textContent=d.text;node.setAttribute("fill",d.stroke||"#fff");node.setAttribute("font-size","24");}
        else {node=document.createElementNS("http://www.w3.org/2000/svg","rect");node.setAttribute("x",d.x);node.setAttribute("y",d.y);node.setAttribute("width",Math.abs(d.width));node.setAttribute("height",Math.abs(d.height));node.setAttribute("fill",d.fill||"transparent");}
        node.setAttribute("stroke",d.stroke||"#b23750"); node.setAttribute("stroke-width",d.stroke_width||3); node.style.pointerEvents="stroke"; node.dataset.objectType="drawings";node.dataset.objectId=d.id;bindObject(node,"drawings",d);svg.append(node);
    }
}
function renderRegions(){const layer=$("#region-layer");layer.innerHTML="";for(const r of state.objects.regions){const el=document.createElement("div");el.className=`region ${r.shape} ${state.selected?.type==='regions'&&state.selected.id===r.id?'selected':''}`;el.dataset.objectType="regions";el.dataset.objectId=r.id;Object.assign(el.style,{left:`${r.x}px`,top:`${r.y}px`,width:`${r.width}px`,height:`${r.height}px`,borderColor:r.color,backgroundColor:`${r.color}18`});el.innerHTML=`<span>${escapeHtml(r.name)}</span>`;bindObject(el,"regions",r);layer.append(el);}}
function tokenCanMove(token){return state.canManage || (state.role!=="spectator"&&token.owner_user_id===state.me.id&&!token.locked);}
function renderTokens(){const layer=$("#token-layer");layer.innerHTML="";for(const t of state.objects.tokens){const el=document.createElement("div");el.className=`token ${t.disposition} ${t.locked?'locked':''} ${state.selectedTokens.has(t.id)||state.selected?.type==='tokens'&&state.selected.id===t.id?'selected':''}`;el.dataset.objectType="tokens";el.dataset.objectId=t.id;Object.assign(el.style,{left:`${t.x}px`,top:`${t.y}px`,width:`${t.width}px`,height:`${t.height}px`,transform:`rotate(${t.rotation}deg)`,backgroundImage:t.image_url?`url("${String(t.image_url).replaceAll('"','%22')}")`:"none"});
        const bar1=t.bar1_max>0?clamp(t.bar1_value/t.bar1_max*100,0,100):0;el.innerHTML=`${t.bar1_max>0?`<div class="token-bars"><span class="token-bar"><i style="width:${bar1}%"></i></span></div>`:''}<span class="token-label">${escapeHtml(t.name)}</span>${t.status?.length?`<span class="token-statuses">${t.status.slice(0,4).map(s=>`<b>${escapeHtml(String(s).slice(0,1))}</b>`).join('')}</span>`:''}`;
        bindObject(el,"tokens",t); if(tokenCanMove(t)) el.addEventListener("pointerdown",startTokenDrag); layer.append(el);
    }}
function renderWalls(){const svg=$("#wall-layer"),doors=$("#door-layer");svg.innerHTML="";doors.innerHTML="";for(const w of state.objects.walls){const line=document.createElementNS("http://www.w3.org/2000/svg","line");line.setAttribute("x1",w.x1);line.setAttribute("y1",w.y1);line.setAttribute("x2",w.x2);line.setAttribute("y2",w.y2);line.classList.add("wall-line",w.wall_type);if(w.door_state==="open")line.classList.add("open");line.dataset.objectType="walls";line.dataset.objectId=w.id;if(canSeeMaster()||state.canManage&&state.tool==="erase"){line.style.pointerEvents="stroke";bindObject(line,"walls",w);}svg.append(line);
        if(w.wall_type!=="wall"){const handle=document.createElement("button");handle.className="door-handle";handle.type="button";handle.style.left=`${(w.x1+w.x2)/2}px`;handle.style.top=`${(w.y1+w.y2)/2}px`;handle.textContent=w.door_state==="open"?"◌":w.door_state==="locked"?"⌑":"◆";handle.title=w.wall_type==="secret"&&state.canManage?"Porta secreta":`Porta ${w.door_state}`;handle.addEventListener("click",()=>toggleDoor(w));doors.append(handle);}}
    svg.hidden=!canSeeMaster()&&state.tool!=="wall";
}
function renderNotes(){const layer=$("#note-layer");layer.innerHTML="";for(const n of state.objects.notes){const el=document.createElement("button");el.type="button";el.className="map-note";el.style.left=`${n.x}px`;el.style.top=`${n.y}px`;el.textContent=n.icon||"◆";el.title=n.title;el.addEventListener("click",async e=>{if(state.tool==="erase"&&state.canManage){e.stopPropagation();await eraseObject("map-notes",n);return;}viewRecord("Nota no mapa",n.title,n.content);});if(state.canManage)el.addEventListener("contextmenu",e=>showContext(e,"map-notes",n));layer.append(el);}}
function renderGmMarkers(){const layer=$("#gm-layer");layer.innerHTML="";if(!canSeeMaster())return;for(const l of state.objects.lights){const el=gmMarker(l.x,l.y,"☼",l.name);bindObject(el,"lights",l);layer.append(el);}for(const s of state.objects.sounds){const el=gmMarker(s.x,s.y,"♫",s.name);bindObject(el,"sounds",s);layer.append(el);}}
function gmMarker(x,y,icon,title){const el=document.createElement("button");el.type="button";el.className="gm-marker";el.style.left=`${x}px`;el.style.top=`${y}px`;el.textContent=icon;el.title=title;return el;}
function renderWeather(){const layer=$("#weather-layer");layer.className=`weather-layer ${state.scene.weather_effect||''}`;}
function renderPings(){const layer=$("#ping-layer");const ids=new Set($$(".ping",layer).map(x=>Number(x.dataset.id)));for(const p of state.pings){if(ids.has(p.id))continue;const el=document.createElement("button");el.type="button";el.className=`ping ${p.ping_type}`;el.dataset.id=p.id;el.style.left=`${p.x}px`;el.style.top=`${p.y}px`;const canErase=state.canManage||p.user_id===state.me.id;if(state.tool==="erase"&&canErase){el.style.pointerEvents="auto";el.title="Apagar ping";el.onclick=async e=>{e.stopPropagation();await api(`/api/vtt/pings/${p.id}`,{method:"DELETE"});state.pings=state.pings.filter(x=>x.id!==p.id);el.remove();};}layer.append(el);setTimeout(()=>el.remove(),6500);}}

function bindObject(el,type,obj){el.addEventListener("click",async e=>{if(state.tool==="erase"){e.stopPropagation();await eraseObject(type,obj);return;}if(state.tool!=="select")return;e.stopPropagation();selectObject(type,obj,e.shiftKey);});el.addEventListener("contextmenu",e=>{if(!state.canManage)return;showContext(e,type,obj);});}
async function eraseObject(type,obj){
    const ownDrawing=type==="drawings"&&obj.author_user_id===state.me.id;
    if(!state.canManage&&!ownDrawing){toast("A borracha só remove as suas próprias marcações.");return;}
    await api(`/api/vtt/${type}/${obj.id}`,{method:"DELETE"});
    await refreshScene();
}

function selectObject(type,obj,multi=false){if(type==="tokens"&&multi){state.selectedTokens.has(obj.id)?state.selectedTokens.delete(obj.id):state.selectedTokens.add(obj.id);}else{state.selectedTokens.clear();if(type==="tokens")state.selectedTokens.add(obj.id);}state.selected={type,id:obj.id,data:obj};renderScene();renderInspector();}
function clearSelection(){state.selected=null;state.selectedTokens.clear();renderScene();renderInspector();}

function renderInspector(){const panel=$("#object-inspector");if(!state.selected){panel.hidden=true;return;}const {type,data}=state.selected;panel.hidden=false;$("#inspector-title").textContent=data.name||data.title||type;let html="";
    if(type==="tokens")html=`${inspectorField("Nome",data.name,"name")}${inspectorField("X",data.x,"x","number")}${inspectorField("Y",data.y,"y","number")}${inspectorField("Tamanho",data.width,"width","number")}${inspectorField("Rotação",data.rotation,"rotation","number")}${inspectorField("Visão",data.vision_range,"visionRange","number")}${inspectorField("Vida",data.bar1_value,"bar1Value","number")}${inspectorField("Vida máx.",data.bar1_max,"bar1Max","number")}<div class="inspector-actions">${state.canManage?'<button class="ghost-button" data-inspector-action="save">Salvar</button><button class="danger-button" data-inspector-action="delete">Excluir</button>':''}</div>`;
    else if(type==="walls")html=`${inspectorSelect("Tipo",data.wall_type,"wallType",[["wall","Parede"],["door","Porta"],["secret","Porta secreta"]])}${inspectorSelect("Estado",data.door_state,"doorState",[["closed","Fechada"],["open","Aberta"],["locked","Trancada"]])}${inspectorCheck("Bloqueia visão",data.blocks_vision,"blocksVision")}${inspectorCheck("Bloqueia movimento",data.blocks_movement,"blocksMovement")}${inspectorCheck("Bloqueia som",data.blocks_sound,"blocksSound")}<div class="inspector-actions"><button class="ghost-button" data-inspector-action="save">Salvar</button><button class="danger-button" data-inspector-action="delete">Excluir</button></div>`;
    else html=`<p style="color:var(--muted);font-size:.62rem">${escapeHtml(type)}</p>${inspectorField("X",data.x??0,"x","number")}${inspectorField("Y",data.y??0,"y","number")}<div class="inspector-actions">${state.canManage?'<button class="ghost-button" data-inspector-action="save">Salvar posição</button><button class="danger-button" data-inspector-action="delete">Excluir</button>':''}</div>`;
    $("#inspector-content").innerHTML=html;$$('[data-inspector-action="save"]').forEach(b=>b.addEventListener("click",saveInspector));$$('[data-inspector-action="delete"]').forEach(b=>b.addEventListener("click",deleteSelected));
}
function inspectorField(label,value,name,type="text"){return `<div class="inspector-field"><label>${label}</label><input data-inspector-field="${name}" type="${type}" value="${escapeHtml(value??'')}"></div>`;}
function inspectorSelect(label,value,name,options){return `<div class="inspector-field"><label>${label}</label><select data-inspector-field="${name}">${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function inspectorCheck(label,value,name){return `<div class="inspector-field"><label><input data-inspector-field="${name}" type="checkbox" ${value?'checked':''}> ${label}</label></div>`;}
async function saveInspector(){if(!state.selected||!state.canManage)return;const body={};$$('[data-inspector-field]').forEach(el=>{body[el.dataset.inspectorField]=el.type==="checkbox"?el.checked:(el.type==="number"?Number(el.value):el.value)});await api(`/api/vtt/${state.selected.type}/${state.selected.id}`,{method:"PATCH",body:JSON.stringify(body)});await refreshScene();toast("Objeto atualizado.");}
async function deleteSelected(){if(!state.selected||!state.canManage)return;if(!confirm("Excluir este objeto da cena?"))return;await api(`/api/vtt/${state.selected.type}/${state.selected.id}`,{method:"DELETE"});state.selected=null;await refreshScene();}

function showContext(event,type,obj){event.preventDefault();event.stopPropagation();const menu=$("#context-menu");menu.hidden=false;menu.style.left=`${Math.min(event.clientX,innerWidth-190)}px`;menu.style.top=`${Math.min(event.clientY,innerHeight-180)}px`;menu.innerHTML=`<button data-act="inspect">Editar / Inspector</button>${type==='tokens'?'<button data-act="duplicate">Duplicar token</button>':''}${type==='walls'&&obj.wall_type!=='wall'?'<button data-act="door">Abrir / fechar</button>':''}<button class="danger" data-act="delete">Excluir</button>`;menu.querySelector('[data-act="inspect"]').onclick=()=>{selectObject(type,obj);menu.hidden=true};const del=menu.querySelector('[data-act="delete"]');del.onclick=async()=>{menu.hidden=true;selectObject(type,obj);await deleteSelected();};const door=menu.querySelector('[data-act="door"]');if(door)door.onclick=async()=>{menu.hidden=true;await toggleDoor(obj)};const dup=menu.querySelector('[data-act="duplicate"]');if(dup)dup.onclick=async()=>{menu.hidden=true;await api(`/api/vtt/scenes/${state.scene.id}/tokens`,{method:"POST",body:JSON.stringify({...tokenBody(obj),x:obj.x+20,y:obj.y+20})});await refreshScene();};}
function tokenBody(t){return {name:t.name,imageUrl:t.image_url,x:t.x,y:t.y,width:t.width,height:t.height,rotation:t.rotation,elevation:t.elevation,hidden:Boolean(t.hidden),locked:Boolean(t.locked),visionEnabled:Boolean(t.vision_enabled),visionRange:t.vision_range,disposition:t.disposition,bar1Value:t.bar1_value,bar1Max:t.bar1_max,bar2Value:t.bar2_value,bar2Max:t.bar2_max,status:t.status,ownerUserId:t.owner_user_id,characterId:t.character_id,npcId:t.npc_id};}

function setTool(tool){if(!toolConfig[tool])return;if(!state.canManage&&["token","tile","wall","light","sound","note","region","fog","fx"].includes(tool))return;state.tool=tool;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$("#viewport").dataset.tool=tool;renderToolOptions();}
function renderToolOptions(){const box=$("#tool-options");if(!state.scene){box.innerHTML="";return;}const size=state.scene.grid_size||70;let html=`<span class="scene-chip muted">${toolConfig[state.tool]?.label||state.tool}</span>`;
    if(state.tool==="measure")html+=`<label>Medida <select id="measure-type"><option value="ruler">Régua</option><option value="radius">Raio</option><option value="cone">Cone 60°</option></select></label>`;
    if(state.tool==="wall")html+=`<label>Tipo <select id="wall-type"><option value="wall">Parede</option><option value="door">Porta</option><option value="secret">Porta secreta</option></select></label><label><input id="wall-move" type="checkbox" checked> movimento</label><label><input id="wall-vision" type="checkbox" checked> visão</label>`;
    if(state.tool==="draw")html+=`<label>Forma <select id="draw-type"><option value="freehand">Livre</option><option value="rect">Retângulo</option><option value="ellipse">Elipse</option><option value="text">Texto</option></select></label><label>Cor <input id="draw-color" type="color" value="#b23750"></label><label>Traço <input id="draw-width" type="number" min="1" max="20" value="3" style="width:50px"></label>`;
    if(state.tool==="fog")html+=`<label>Modo <select id="fog-mode"><option value="reveal" ${state.fogMode==="reveal"?"selected":""}>Revelar</option><option value="hide" ${state.fogMode==="hide"?"selected":""}>Ocultar</option></select></label><button class="mini-button" id="fog-reset" type="button">Resetar revelado</button>${state.scene.explorer_enabled?'<button class="mini-button" id="fog-explorer-reset" type="button">Limpar Explorer</button>':''}`;
    if(state.tool==="erase")html+=state.canManage?`<span class="scene-chip muted">Clique em qualquer objeto para apagar</span><button class="mini-button" id="clear-markings" type="button">Limpar marcações da cena</button>`:`<span class="scene-chip muted">Clique nos seus desenhos ou pings para apagar</span>`;
    if(["token","tile","region"].includes(state.tool))html+=`<label><input id="snap-grid" type="checkbox" checked> snap ${size}px</label>`;
    box.innerHTML=html;const fogMode=$("#fog-mode");if(fogMode)fogMode.onchange=()=>{state.fogMode=fogMode.value==="hide"?"hide":"reveal";};const reset=$("#fog-reset");if(reset)reset.onclick=async()=>{if(!confirm("Resetar as áreas reveladas manualmente desta cena?"))return;state.fog.global.revealed=[];await saveFogGlobal();renderFog();};const explorerReset=$("#fog-explorer-reset");if(explorerReset)explorerReset.onclick=async()=>{if(!confirm("Apagar o histórico do Explorer de todos os jogadores nesta cena?"))return;await api(`/api/vtt/scenes/${state.scene.id}/fog/explorer`,{method:"DELETE"});state.fog.user.explored=[];state.explorerGeneration++;renderFog();toast("Histórico do Explorer limpo.");};const clear=$("#clear-markings");if(clear)clear.onclick=async()=>{if(!confirm("Apagar desenhos, paredes, notas, regiões e pings desta cena? Tokens, tiles e o mapa serão preservados."))return;await api(`/api/vtt/scenes/${state.scene.id}/clear-markings`,{method:"POST"});await refreshScene();toast("Marcações da cena limpas.");};
}
$$('[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));

function stagePoint(event){const r=$("#viewport").getBoundingClientRect();return {x:(event.clientX-r.left-state.panX)/state.zoom,y:(event.clientY-r.top-state.panY)/state.zoom};}
function applyStageTransform(){const stage=$("#stage");stage.style.transform=`translate(${state.panX}px,${state.panY}px) scale(${state.zoom})`;$("#zoom-label").textContent=`${Math.round(state.zoom*100)}%`;}
function fitScene(){if(!state.scene)return;const vp=$("#viewport").getBoundingClientRect();const z=Math.min(vp.width/state.scene.width,vp.height/state.scene.height)*.92;state.zoom=clamp(z,.1,3);state.panX=(vp.width-state.scene.width*state.zoom)/2;state.panY=(vp.height-state.scene.height*state.zoom)/2;applyStageTransform();}
function zoomAt(delta,clientX,clientY){if(!state.scene)return;const vp=$("#viewport").getBoundingClientRect();const before={x:(clientX-vp.left-state.panX)/state.zoom,y:(clientY-vp.top-state.panY)/state.zoom};const next=clamp(state.zoom*(delta>0?1.12:.89),.1,4);state.panX=clientX-vp.left-before.x*next;state.panY=clientY-vp.top-before.y*next;state.zoom=next;applyStageTransform();}

const viewport=$("#viewport");
viewport.addEventListener("wheel",e=>{e.preventDefault();zoomAt(e.deltaY<0?1:-1,e.clientX,e.clientY)},{passive:false});
viewport.addEventListener("pointermove",e=>{const p=stagePoint(e);$("#scene-coordinates").textContent=`x ${Math.round(p.x)} • y ${Math.round(p.y)}`;state.cursor=p;if(state.drag?.kind==="pan"){state.panX=state.drag.startPanX+(e.clientX-state.drag.clientX);state.panY=state.drag.startPanY+(e.clientY-state.drag.clientY);applyStageTransform();return;}if(state.drag?.kind==="measure")return updateMeasure(p);if(state.drag?.kind==="wall")return updateWallDraft(p);if(state.drag?.kind==="draw")return updateDrawingDraft(p);if(state.drag?.kind==="fog")return updateRectDraft(p,"fog");if(state.drag?.kind==="region")return updateRectDraft(p,"region");});
viewport.addEventListener("pointerdown",e=>{if(!state.scene)return;if(e.button===1||state.tool==="pan"){state.drag={kind:"pan",clientX:e.clientX,clientY:e.clientY,startPanX:state.panX,startPanY:state.panY};viewport.classList.add("dragging");return;}if(e.button!==0)return;const p=stagePoint(e);if(state.tool==="select"){if(e.target===viewport||e.target===$("#stage")||e.target===$("#scene-background")||e.target===$("#grid-layer"))clearSelection();return;}if(state.world.paused&&!state.canManage&&!["pan","measure","ping"].includes(state.tool)){toast("A mesa está pausada.");return;}if(state.tool==="measure")startMeasure(p);else if(state.tool==="ping")sendPing(p,"ping");else if(state.tool==="fx")sendPing(p,"fx");else if(state.tool==="wall")startWallDraft(p);else if(state.tool==="draw")startDrawingDraft(p);else if(state.tool==="fog")startRectDraft(p,"fog");else if(state.tool==="region")startRectDraft(p,"region");else if(state.tool==="token")createTokenAt(p);else if(state.tool==="tile")createTileAt(p);else if(state.tool==="light")createLightAt(p);else if(state.tool==="sound")createSoundAt(p);else if(state.tool==="note")createNoteAt(p);});
window.addEventListener("pointerup",async e=>{if(state.drag?.kind==="pan"){state.drag=null;viewport.classList.remove("dragging");return;}if(state.drag?.kind==="measure"){state.drag=null;return;}if(state.drag?.kind==="wall"){const draft=state.drag;state.drag=null;await finishWallDraft(draft);return;}if(state.drag?.kind==="draw"){const draft=state.drag;state.drag=null;await finishDrawingDraft(draft);return;}if(state.drag?.kind==="fog"){const draft=state.drag;state.drag=null;await finishFogDraft(draft);return;}if(state.drag?.kind==="region"){const draft=state.drag;state.drag=null;await finishRegionDraft(draft);return;}});

function snap(v){const size=state.scene?.grid_size||70;return $("#snap-grid")?.checked===false?v:Math.round(v/size)*size;}
function startMeasure(p){state.drag={kind:"measure",start:p,end:p,measureType:$("#measure-type")?.value||"ruler"};updateMeasure(p);}
function updateMeasure(p){state.drag.end=p;const {start,measureType}=state.drag;const layer=$("#measure-layer");const dx=p.x-start.x,dy=p.y-start.y,distPx=Math.hypot(dx,dy);const cells=distPx/(state.scene.grid_size||70);const distance=cells*(state.scene.grid_distance||1);const label=`${distance.toFixed(1)} ${escapeHtml(state.scene.grid_units||'m')}`;if(measureType==="radius"){layer.innerHTML=`<circle cx="${start.x}" cy="${start.y}" r="${distPx}" fill="rgba(179,55,80,.12)" stroke="#e3c9a2" stroke-width="3" stroke-dasharray="8 5"/><text x="${start.x}" y="${start.y-distPx-8}" fill="#fff" font-size="18" text-anchor="middle">${label}</text>`;return;}if(measureType==="cone"){const a=Math.atan2(dy,dx),half=Math.PI/6,a1=a-half,a2=a+half,x1=start.x+Math.cos(a1)*distPx,y1=start.y+Math.sin(a1)*distPx,x2=start.x+Math.cos(a2)*distPx,y2=start.y+Math.sin(a2)*distPx,large=0;layer.innerHTML=`<path d="M ${start.x} ${start.y} L ${x1} ${y1} A ${distPx} ${distPx} 0 ${large} 1 ${x2} ${y2} Z" fill="rgba(179,55,80,.14)" stroke="#e3c9a2" stroke-width="3" stroke-dasharray="8 5"/><text x="${p.x}" y="${p.y-10}" fill="#fff" font-size="18" text-anchor="middle">${label}</text>`;return;}layer.innerHTML=`<line x1="${start.x}" y1="${start.y}" x2="${p.x}" y2="${p.y}" stroke="#e3c9a2" stroke-width="3" stroke-dasharray="8 5"/><text x="${(start.x+p.x)/2}" y="${(start.y+p.y)/2-8}" fill="#fff" font-size="18" text-anchor="middle">${label}</text>`;}
function startWallDraft(p){state.drag={kind:"wall",start:p,end:p};updateWallDraft(p);}
function updateWallDraft(p){state.drag.end=p;const s=state.drag.start;$("#measure-layer").innerHTML=`<line x1="${s.x}" y1="${s.y}" x2="${p.x}" y2="${p.y}" stroke="#d14d61" stroke-width="4"/>`;}
async function finishWallDraft(d){$("#measure-layer").innerHTML="";if(Math.hypot(d.end.x-d.start.x,d.end.y-d.start.y)<8)return;await api(`/api/vtt/scenes/${state.scene.id}/walls`,{method:"POST",body:JSON.stringify({x1:d.start.x,y1:d.start.y,x2:d.end.x,y2:d.end.y,wallType:$("#wall-type")?.value||"wall",blocksMovement:$("#wall-move")?.checked!==false,blocksVision:$("#wall-vision")?.checked!==false,blocksSound:true})});await refreshScene();}
function startDrawingDraft(p){const drawingType=$("#draw-type")?.value||"freehand";if(drawingType==="text"){openFormDialog({eyebrow:"Drawing Layer",title:"Adicionar texto",fields:`<label>Texto<input name="text" required></label><label>Cor<input name="stroke" type="color" value="${$("#draw-color")?.value||'#b23750'}"></label>`,onSubmit:async fd=>{await api(`/api/vtt/scenes/${state.scene.id}/drawings`,{method:"POST",body:JSON.stringify({drawingType:"text",x:p.x,y:p.y,text:fd.get("text"),stroke:fd.get("stroke"),strokeWidth:Number($("#draw-width")?.value)||3})});await refreshScene();}});return;}state.drag=drawingType==="freehand"?{kind:"draw",drawingType,points:[p]}:{kind:"draw",drawingType,start:p,end:p};}
function updateDrawingDraft(p){const d=state.drag;if(d.drawingType==="freehand"){d.points.push(p);$("#measure-layer").innerHTML=`<polyline points="${d.points.map(x=>`${x.x},${x.y}`).join(' ')}" fill="none" stroke="${$("#draw-color")?.value||'#b23750'}" stroke-width="${Number($("#draw-width")?.value)||3}"/>`;return;}d.end=p;const x=Math.min(d.start.x,p.x),y=Math.min(d.start.y,p.y),w=Math.abs(p.x-d.start.x),h=Math.abs(p.y-d.start.y);$("#measure-layer").innerHTML=d.drawingType==="ellipse"?`<ellipse cx="${x+w/2}" cy="${y+h/2}" rx="${w/2}" ry="${h/2}" fill="transparent" stroke="${$("#draw-color")?.value||'#b23750'}" stroke-width="${Number($("#draw-width")?.value)||3}"/>`:`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="transparent" stroke="${$("#draw-color")?.value||'#b23750'}" stroke-width="${Number($("#draw-width")?.value)||3}"/>`;}
async function finishDrawingDraft(d){$("#measure-layer").innerHTML="";const stroke=$("#draw-color")?.value||"#b23750",strokeWidth=Number($("#draw-width")?.value)||3;if(d.drawingType==="freehand"){if(d.points.length<2)return;await api(`/api/vtt/scenes/${state.scene.id}/drawings`,{method:"POST",body:JSON.stringify({drawingType:"freehand",points:d.points,stroke,strokeWidth})});}else{const x=Math.min(d.start.x,d.end.x),y=Math.min(d.start.y,d.end.y),width=Math.abs(d.end.x-d.start.x),height=Math.abs(d.end.y-d.start.y);if(width<5||height<5)return;await api(`/api/vtt/scenes/${state.scene.id}/drawings`,{method:"POST",body:JSON.stringify({drawingType:d.drawingType,x,y,width,height,stroke,fill:"transparent",strokeWidth})});}await refreshScene();}
function startRectDraft(p,kind){state.drag={kind,start:p,end:p};updateRectDraft(p,kind);}
function updateRectDraft(p,kind){state.drag.end=p;const s=state.drag.start,x=Math.min(s.x,p.x),y=Math.min(s.y,p.y),w=Math.abs(p.x-s.x),h=Math.abs(p.y-s.y);$("#measure-layer").innerHTML=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${kind==='fog'?'rgba(120,20,40,.18)':'rgba(125,26,42,.12)'}" stroke="#b23750" stroke-width="2" stroke-dasharray="7 5"/>`;}
async function finishFogDraft(d){$("#measure-layer").innerHTML="";const x=Math.min(d.start.x,d.end.x),y=Math.min(d.start.y,d.end.y),w=Math.abs(d.end.x-d.start.x),h=Math.abs(d.end.y-d.start.y);if(w<8||h<8)return;const area={x,y,w,h},mode=state.fogMode||"reveal";if(mode==="reveal")state.fog.global.revealed.push(area);else state.fog.global.revealed=state.fog.global.revealed.flatMap(r=>subtractRect(r,area));await saveFogGlobal();renderFog();}
async function finishRegionDraft(d){$("#measure-layer").innerHTML="";const x=Math.min(d.start.x,d.end.x),y=Math.min(d.start.y,d.end.y),width=Math.abs(d.end.x-d.start.x),height=Math.abs(d.end.y-d.start.y);if(width<12||height<12)return;openFormDialog({eyebrow:"Scene Region",title:"Criar região",fields:`<label>Nome<input name="name" value="Região"></label><label>Forma<select name="shape"><option value="rect">Retângulo</option><option value="ellipse">Elipse</option></select></label><label>Comportamento / aviso<textarea name="message" placeholder="Mensagem ao entrar na região"></textarea></label>`,onSubmit:async fd=>{await api(`/api/vtt/scenes/${state.scene.id}/regions`,{method:"POST",body:JSON.stringify({name:fd.get("name"),shape:fd.get("shape"),x,y,width,height,behavior:{message:fd.get("message")}})});await refreshScene();}});}
async function saveFogGlobal(){
    const generation=++state.fogGeneration;
    state.fogWritePending++;
    const revealed=structuredClone(state.fog.global.revealed||[]);
    try{
        const result=await api(`/api/vtt/scenes/${state.scene.id}/fog`,{method:"PUT",body:JSON.stringify({scope:"global",revealed})});
        if(Array.isArray(result.revealed)&&state.fogGeneration===generation)state.fog.global.revealed=result.revealed;
        state.fogGeneration=Math.max(state.fogGeneration,generation)+1;
    } finally { state.fogWritePending=Math.max(0,state.fogWritePending-1); }
}

function startTokenDrag(event){if(state.tool!=="select")return;event.stopPropagation();const id=Number(event.currentTarget.dataset.objectId),token=state.objects.tokens.find(t=>t.id===id);if(!tokenCanMove(token))return;const start=stagePoint(event);state.drag={kind:"token",id,token,start,orig:{x:token.x,y:token.y},offset:{x:start.x-token.x,y:start.y-token.y}};event.currentTarget.setPointerCapture?.(event.pointerId);const move=ev=>dragTokenMove(ev);const up=async ev=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",up);await finishTokenDrag(ev);};window.addEventListener("pointermove",move);window.addEventListener("pointerup",up,{once:true});}
function dragTokenMove(event){if(state.drag?.kind!=="token")return;const p=stagePoint(event),t=state.drag.token;let nx=p.x-state.drag.offset.x,ny=p.y-state.drag.offset.y;if(event.shiftKey===false&&state.scene.grid_type!=="gridless"){const size=state.scene.grid_size;nx=Math.round(nx/size)*size;ny=Math.round(ny/size)*size;}const centerOld={x:state.drag.orig.x+t.width/2,y:state.drag.orig.y+t.height/2},centerNew={x:nx+t.width/2,y:ny+t.height/2};if(state.scene.restrict_movement&&!state.canManage&&movementBlocked(centerOld,centerNew)){return;}t.x=nx;t.y=ny;renderTokens();renderLighting();renderFog();}
async function finishTokenDrag(){if(state.drag?.kind!=="token")return;const t=state.drag.token;state.drag=null;await api(`/api/vtt/tokens/${t.id}`,{method:"PATCH",body:JSON.stringify({x:t.x,y:t.y,rotation:t.rotation})});await rememberExplored(t);await refreshScene();checkRegions(t);}
function movementBlocked(a,b){return state.objects.walls.some(w=>w.blocks_movement&&!(w.wall_type!=="wall"&&w.door_state==="open")&&segmentsIntersect(a,b,{x:w.x1,y:w.y1},{x:w.x2,y:w.y2}));}
function segmentsIntersect(a,b,c,d){const ccw=(p1,p2,p3)=>(p3.y-p1.y)*(p2.x-p1.x)>(p2.y-p1.y)*(p3.x-p1.x);return ccw(a,c,d)!==ccw(b,c,d)&&ccw(a,b,c)!==ccw(a,b,d);}
function checkRegions(token){const cx=token.x+token.width/2,cy=token.y+token.height/2;for(const r of state.objects.regions){const inside=r.shape==="ellipse"?(((cx-(r.x+r.width/2))/(r.width/2))**2+((cy-(r.y+r.height/2))/(r.height/2))**2<=1):(cx>=r.x&&cx<=r.x+r.width&&cy>=r.y&&cy<=r.y+r.height);if(inside&&r.behavior?.message)toast(`${r.name}: ${r.behavior.message}`);}}
async function rememberExplored(token){
    if(!state.scene.explorer_enabled||token.owner_user_id!==state.me.id||!token.vision_enabled)return;
    const generation=++state.explorerGeneration;
    state.explorerWritePending++;
    try{
        const result=await api(`/api/vtt/scenes/${state.scene.id}/fog`,{method:"PUT",body:JSON.stringify({scope:"user",tokenId:token.id})});
        if(result.exploredShape){
            state.fog.user.explored.push(result.exploredShape);
            if(state.fog.user.explored.length>100)state.fog.user.explored=state.fog.user.explored.slice(-100);
        }
        state.explorerGeneration=Math.max(state.explorerGeneration,generation)+1;
    } finally { state.explorerWritePending=Math.max(0,state.explorerWritePending-1); }
}

async function toggleDoor(w){if(state.world.paused&&!state.canManage){toast("A mesa está pausada.");return;}await api(`/api/vtt/walls/${w.id}/toggle`,{method:"POST"});await refreshScene();}
async function sendPing(p,type="ping"){const d=await api(`/api/vtt/scenes/${state.scene.id}/pings`,{method:"POST",body:JSON.stringify({x:p.x,y:p.y,pingType:type})});const local={id:d.id,x:p.x,y:p.y,ping_type:type,user_id:state.me.id,user_name:state.me.name};state.pings.push(local);renderPings();}

function createTokenAt(p){const charOptions=state.characters.map(c=>`<option value="c:${c.id}">${escapeHtml(c.name)} — personagem</option>`).join(''),npcOptions=state.npcs.map(n=>`<option value="n:${n.id}">${escapeHtml(n.name)} — NPC</option>`).join('');openFormDialog({eyebrow:"Actor Token",title:"Adicionar token",fields:`<label>Origem<select name="source"><option value="">Token avulso</option>${charOptions}${npcOptions}</select></label><label>Nome<input name="name" placeholder="Nome exibido"></label><label>Imagem do token<input name="imageFile" type="file" accept="image/*"><small>Escolha uma imagem do seu PC. Se usar um personagem/NPC e não escolher arquivo, será usada a imagem já salva nele.</small></label><div class="field-grid two"><label>Disposição<select name="disposition"><option value="friendly">Aliado</option><option value="neutral" selected>Neutro</option><option value="hostile">Hostil</option><option value="secret">Secreto</option></select></label><label>Visão<input name="visionRange" type="number" value="420"></label></div>`,onSubmit:async fd=>{const source=String(fd.get('source')||'');let ref={};let name=fd.get('name'),imageUrl='',ownerUserId=null,bar1Value=0,bar1Max=0;if(source.startsWith('c:')){const c=state.characters.find(x=>x.id===Number(source.slice(2)));ref.characterId=c.id;name=name||c.name;imageUrl=c.avatar_url;ownerUserId=c.user_id;bar1Value=c.health_current;bar1Max=c.health_max;}if(source.startsWith('n:')){const n=state.npcs.find(x=>x.id===Number(source.slice(2)));ref.npcId=n.id;name=name||n.name;imageUrl=n.image_url;bar1Value=n.health;bar1Max=n.health;}const file=fd.get('imageFile');if(file instanceof File&&file.size)imageUrl=await uploadFile(file,'image');await api(`/api/vtt/scenes/${state.scene.id}/tokens`,{method:'POST',body:JSON.stringify({...ref,name:name||'Token',imageUrl,x:snap(p.x),y:snap(p.y),width:state.scene.grid_size,height:state.scene.grid_size,disposition:fd.get('disposition'),visionRange:Number(fd.get('visionRange'))||420,ownerUserId,bar1Value,bar1Max})});await refreshScene();}});}
function createTileAt(p){openFormDialog({eyebrow:"Tile Layer",title:"Adicionar imagem / tile",fields:`<label>Nome<input name="name" value="Tile"></label><label>Imagem do PC<input name="imageFile" type="file" accept="image/*" required></label><div class="field-grid three"><label>Largura<input name="width" type="number" value="350"></label><label>Altura<input name="height" type="number" value="350"></label><label>Camada<select name="layer"><option value="under">Abaixo dos tokens</option><option value="over">Acima dos tokens</option><option value="gm">Somente Mestre</option></select></label></div>`,onSubmit:async fd=>{const imageUrl=await uploadFile(fd.get('imageFile'),'image');await api(`/api/vtt/scenes/${state.scene.id}/tiles`,{method:'POST',body:JSON.stringify({name:fd.get('name'),imageUrl,x:snap(p.x),y:snap(p.y),width:Number(fd.get('width')),height:Number(fd.get('height')),layer:fd.get('layer')})});await refreshScene();}});}
function createLightAt(p){openFormDialog({eyebrow:"Lighting",title:"Nova fonte de luz",fields:`<label>Nome<input name="name" value="Luz"></label><div class="field-grid three"><label>Raio forte<input name="bright" type="number" value="140"></label><label>Raio suave<input name="dim" type="number" value="280"></label><label>Cor<input name="color" type="color" value="#f6d59a"></label></div>`,onSubmit:async fd=>{await api(`/api/vtt/scenes/${state.scene.id}/lights`,{method:'POST',body:JSON.stringify({name:fd.get('name'),x:p.x,y:p.y,brightRadius:Number(fd.get('bright')),dimRadius:Number(fd.get('dim')),color:fd.get('color')})});await refreshScene();}});}
function createSoundAt(p){openFormDialog({eyebrow:"Ambient Sound",title:"Som posicional",fields:`<label>Nome<input name="name" value="Som ambiente"></label><label>URL de áudio direto<input name="url" placeholder="https://.../arquivo.mp3"></label><div class="field-grid two"><label>Raio<input name="radius" type="number" value="420"></label><label>Volume<input name="volume" type="number" min="0" max="1" step=".05" value=".7"></label></div>`,onSubmit:async fd=>{await api(`/api/vtt/scenes/${state.scene.id}/sounds`,{method:'POST',body:JSON.stringify({name:fd.get('name'),url:fd.get('url'),x:p.x,y:p.y,radius:Number(fd.get('radius')),volume:Number(fd.get('volume'))})});await refreshScene();}});}
function createNoteAt(p){openFormDialog({eyebrow:"Map Note",title:"Fixar nota no mapa",fields:`<label>Título<input name="title" value="Nota"></label><label>Conteúdo<textarea name="content"></textarea></label><label>Visibilidade<select name="visibility"><option value="all">Todos</option><option value="master">Somente Mestre</option></select></label>`,onSubmit:async fd=>{await api(`/api/vtt/scenes/${state.scene.id}/map-notes`,{method:'POST',body:JSON.stringify({title:fd.get('title'),content:fd.get('content'),visibility:fd.get('visibility'),x:p.x,y:p.y})});await refreshScene();}});}

function ownedTokens(){return state.objects.tokens.filter(t=>t.owner_user_id===state.me?.id&&!t.hidden);}
function visionTokens(){
    if(state.playerView&&state.canManage){
        const selected=state.selected?.type==="tokens"?state.objects.tokens.find(t=>t.id===state.selected.id&&t.vision_enabled&&!t.hidden):null;
        return selected?[selected]:(state.objects.tokens.find(t=>t.vision_enabled&&!t.hidden)?[state.objects.tokens.find(t=>t.vision_enabled&&!t.hidden)]:[]);
    }
    return ownedTokens().filter(t=>t.vision_enabled);
}
function visionToken(){return visionTokens()[0]||ownedTokens()[0]||null;}
function visionPolygon(token){return computeVisionPolygon(token,state.objects.walls,{width:state.scene?.width,height:state.scene?.height}); }
function carvePolygon(ctx,poly){if(poly.length<3)return;ctx.beginPath();ctx.moveTo(poly[0].x,poly[0].y);for(const p of poly.slice(1))ctx.lineTo(p.x,p.y);ctx.closePath();ctx.fill();}
function renderLighting(){if(!state.scene)return;const canvas=$("#lighting-layer"),ctx=canvas.getContext("2d");ctx.clearRect(0,0,canvas.width,canvas.height);const simulation=!state.canManage||state.playerView;const darkness=clamp(state.scene.darkness,0,1);ctx.fillStyle=`rgba(0,0,0,${simulation && !state.scene.global_illumination ? 0.94 : darkness})`;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.globalCompositeOperation="destination-out";
    for(const l of state.objects.lights){const g=ctx.createRadialGradient(l.x,l.y,Math.max(0,l.bright_radius*.15),l.x,l.y,l.dim_radius);g.addColorStop(0,"rgba(0,0,0,1)");g.addColorStop(Math.min(.95,l.bright_radius/Math.max(1,l.dim_radius)),"rgba(0,0,0,.9)");g.addColorStop(1,"rgba(0,0,0,0)");ctx.fillStyle=g;ctx.beginPath();ctx.arc(l.x,l.y,l.dim_radius,0,Math.PI*2);ctx.fill();}
    if(simulation){ctx.fillStyle="rgba(0,0,0,1)";for(const token of visionTokens())carvePolygon(ctx,visionPolygon(token));}
    ctx.globalCompositeOperation="source-over";
}
function carveFogShape(ctx,raw){const shape=normalizeFogShape(raw);if(!shape)return;if(shape.type==="polygon")carvePolygon(ctx,shape.points);else ctx.fillRect(shape.x,shape.y,shape.w,shape.h);}
function renderFog(){
    if(!state.scene)return;
    const canvas=$("#fog-layer"),ctx=canvas.getContext("2d");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    if(!state.scene.fog_enabled)return;
    const simulation=!state.canManage||state.playerView;
    ctx.fillStyle=`rgba(4,4,6,${simulation ? 0.97 : 0.45})`;ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.globalCompositeOperation="destination-out";ctx.fillStyle="#000";
    for(const r of state.fog.global.revealed||[])carveFogShape(ctx,r);
    if(state.scene.explorer_enabled)for(const shape of state.fog.user.explored||[])carveFogShape(ctx,shape);
    if(simulation)for(const t of visionTokens())carvePolygon(ctx,visionPolygon(t));
    ctx.globalCompositeOperation="source-over";
}

function updateAmbientSounds(){for(const [id,audio] of state.ambientAudio){if(!state.objects.sounds.some(s=>s.id===id)){audio.pause();state.ambientAudio.delete(id);}}const t=visionToken();const cx=t?t.x+t.width/2:null,cy=t?t.y+t.height/2:null;for(const s of state.objects.sounds){if(!s.url||!/^https?:/i.test(s.url))continue;let audio=state.ambientAudio.get(s.id);if(!audio){audio=new Audio(s.url);audio.loop=true;audio.preload="none";state.ambientAudio.set(s.id,audio);audio.play().catch(()=>{});}let factor=1;if(cx!=null){const d=Math.hypot(cx-s.x,cy-s.y);factor=clamp(1-d/s.radius,0,1);}audio.volume=clamp(s.volume*state.localVolumes.ambient*factor,0,1);if(audio.volume>0&&audio.paused)audio.play().catch(()=>{});}}

function mergeIncomingFog(incoming,globalGenAtStart,explorerGenAtStart){
    state.fog=mergeFogSnapshots(state.fog,incoming,{
        globalPending:state.fogWritePending>0,globalGenerationAtStart:globalGenAtStart,currentGlobalGeneration:state.fogGeneration,
        explorerPending:state.explorerWritePending>0,explorerGenerationAtStart:explorerGenAtStart,currentExplorerGeneration:state.explorerGeneration
    });
}
async function refreshScene(){if(!state.scene)return;const current=state.scene.id,globalGen=state.fogGeneration,explorerGen=state.explorerGeneration;const data=await api(`/api/vtt/scenes/${current}`);state.scene=data.scene;state.objects=data.objects;mergeIncomingFog(data.fog,globalGen,explorerGen);state.pings=data.pings;renderScene();renderInspector();updateAmbientSounds();}

// ----- Diretórios / Sidebar -----
function openDirectory(name){$$('[data-directory]').forEach(b=>b.classList.toggle('active',b.dataset.directory===name));$$('[data-directory-pane]').forEach(p=>p.classList.toggle('active',p.dataset.directoryPane===name));}
$$('[data-directory]').forEach(b=>b.addEventListener('click',()=>openDirectory(b.dataset.directory)));
function renderDirectories(){renderCombat();renderSceneDirectory();renderActors();renderItems();renderJournal();renderTables();renderDecks();renderMedia();renderCutscenes();renderCompendium();}
function renderOnline(){const online=state.members.filter(m=>m.is_online);$("#online-status span").textContent=`${online.length} online`;$("#online-status").title=online.map(x=>x.name).join(', ')||'Ninguém online';const recipient=$("#chat-recipient");recipient.innerHTML=state.members.filter(m=>m.id!==state.me.id).map(m=>`<option value="${m.id}">${escapeHtml(m.name)}</option>`).join('');}

function renderSceneDirectory(filter="") {const box=$("#scene-directory");if(!box)return;const q=filter.toLowerCase();const grouped=new Map();for(const scene of state.scenes.filter(s=>s.title.toLowerCase().includes(q))){const key=scene.folder_id||0;if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(scene);}let html="";for(const [folderId,scenes] of grouped){if(folderId){const f=state.folders.find(x=>x.id===folderId);html+=`<div class="directory-folder">${escapeHtml(f?.name||'Pasta')}</div>`;}for(const s of scenes)html+=`<div class="directory-item ${state.scene?.id===s.id?'active':''}" data-scene-row="${s.id}"><span class="directory-item-thumb" style="background-image:${s.image_url?`url('${escapeHtml(s.image_url)}')`:'none'}">${s.image_url?'':'▣'}</span><div class="directory-item-main"><strong>${escapeHtml(s.title)}</strong><small>${s.is_current?'Cena ativa · ':''}${s.gm_only?'Somente Mestre · ':''}${s.grid_type}</small></div><div class="directory-item-actions"><button data-scene-open="${s.id}" title="Ver">◎</button>${state.canManage?`<button data-scene-activate="${s.id}" title="Ativar">▶</button><button data-scene-edit="${s.id}" title="Editar">⚙</button>`:''}</div></div>`;}
    box.innerHTML=html||`<div class="empty-state">Nenhuma cena encontrada.</div>`;$$('[data-scene-open]',box).forEach(b=>b.onclick=()=>openScene(Number(b.dataset.sceneOpen),{fit:true}));$$('[data-scene-activate]',box).forEach(b=>b.onclick=()=>activateScene(Number(b.dataset.sceneActivate)));$$('[data-scene-edit]',box).forEach(b=>b.onclick=()=>editScene(Number(b.dataset.sceneEdit)));}
function renderActors(filter=""){const q=filter.toLowerCase();const chars=state.characters.filter(x=>x.name.toLowerCase().includes(q)),npcs=state.npcs.filter(x=>x.name.toLowerCase().includes(q));$("#actor-directory").innerHTML=`<div class="directory-folder">Personagens</div>${chars.map(c=>actorRow(c,'character')).join('')||'<div class="empty-state">Nenhum personagem.</div>'}${state.canManage?`<div class="directory-folder">NPCs</div>${npcs.map(n=>actorRow(n,'npc')).join('')||'<div class="empty-state">Nenhum NPC.</div>'}`:''}`;$$('[data-actor-view]').forEach(b=>b.onclick=()=>viewActor(b.dataset.actorView));$$('[data-actor-place]').forEach(b=>b.onclick=()=>prepareActorToken(b.dataset.actorPlace));}
function actorRow(a,type){const own=type==='character'&&a.user_id===state.me.id;return `<div class="directory-item"><span class="directory-item-thumb" style="background-image:${a.avatar_url||a.image_url?`url('${escapeHtml(a.avatar_url||a.image_url)}')`:'none'}">${a.avatar_url||a.image_url?'':'◉'}</span><div class="directory-item-main"><strong>${escapeHtml(a.name)}</strong><small>${type==='character'?escapeHtml(a.clan||a.concept||'Personagem'):escapeHtml(a.type||'NPC')}</small></div><div class="directory-item-actions"><button data-actor-view="${type}:${a.id}">◎</button>${state.canManage&&state.scene?`<button data-actor-place="${type}:${a.id}">＋</button>`:''}${own?`<a href="/pages/personagem.html?id=${a.id}" target="_blank" title="Ficha">↗</a>`:''}</div></div>`;}
function viewActor(ref){const [type,idRaw]=ref.split(':'),id=Number(idRaw),a=(type==='character'?state.characters:state.npcs).find(x=>x.id===id);if(!a)return;viewRecord(type==='character'?'Personagem':'NPC',a.name,type==='character'?`Clã: ${a.clan||'—'}\nConceito: ${a.concept||'—'}\nFome: ${a.hunger} · Humanidade: ${a.humanity}\nSaúde: ${a.health_current}/${a.health_max}\nForça de Vontade: ${a.willpower_current}/${a.willpower_max}`:`Tipo: ${a.type}\nImportância: ${a.importance}\nDefesa: ${a.defense} · Saúde: ${a.health} · Dano: ${a.damage}`);}
function prepareActorToken(ref){if(!state.scene)return;const center={x:state.scene.width/2-state.scene.grid_size/2,y:state.scene.height/2-state.scene.grid_size/2};const [type,idRaw]=ref.split(':'),id=Number(idRaw),a=(type==='character'?state.characters:state.npcs).find(x=>x.id===id);const body={name:a.name,imageUrl:a.avatar_url||a.image_url,x:center.x,y:center.y,width:state.scene.grid_size,height:state.scene.grid_size};if(type==='character'){body.characterId=id;body.ownerUserId=a.user_id;body.bar1Value=a.health_current;body.bar1Max=a.health_max;body.disposition='friendly';}else{body.npcId=id;body.bar1Value=a.health;body.bar1Max=a.health;body.disposition='neutral';}api(`/api/vtt/scenes/${state.scene.id}/tokens`,{method:'POST',body:JSON.stringify(body)}).then(refreshScene);}

function renderItems(filter=""){const q=filter.toLowerCase();$("#item-directory").innerHTML=state.items.filter(i=>i.name.toLowerCase().includes(q)).map(i=>`<div class="directory-item"><span class="directory-item-thumb" style="background-image:${i.image_url?`url('${escapeHtml(i.image_url)}')`:'none'}">${i.image_url?'':'◇'}</span><div class="directory-item-main"><strong>${escapeHtml(i.name)}</strong><small>${escapeHtml(i.item_type)}${i.folder?' · '+escapeHtml(i.folder):''}</small></div><div class="directory-item-actions"><button data-item-view="${i.id}">◎</button>${state.canManage?`<button data-item-delete="${i.id}">×</button>`:''}</div></div>`).join('')||'<div class="empty-state">Nenhum item.</div>';$$('[data-item-view]').forEach(b=>b.onclick=()=>{const i=state.items.find(x=>x.id===Number(b.dataset.itemView));viewRecord('Item',i.name,i.description||'Sem descrição.');});$$('[data-item-delete]').forEach(b=>b.onclick=()=>deleteResource(`/api/vtt/items/${b.dataset.itemDelete}`,loadBootstrap));}
function renderJournal(filter=""){const q=filter.toLowerCase();$("#journal-directory").innerHTML=state.journals.filter(j=>(j.title+j.content).toLowerCase().includes(q)).map(j=>`<div class="directory-item"><span class="directory-item-thumb">≡</span><div class="directory-item-main"><strong>${escapeHtml(j.title)}</strong><small>${escapeHtml(j.entry_type)}${j.occurred_at?' · '+escapeHtml(j.occurred_at):''}</small></div><div class="directory-item-actions"><button data-journal-view="${j.id}">◎</button></div></div>`).join('')||'<div class="empty-state">Nenhum registro revelado.</div>';$$('[data-journal-view]').forEach(b=>b.onclick=()=>{const j=state.journals.find(x=>x.id===Number(b.dataset.journalView));viewRecord('Journal',j.title,j.content);});}
function renderTables(){$("#table-directory").innerHTML=state.tables.map(t=>`<div class="directory-item"><span class="directory-item-thumb">⌗</span><div class="directory-item-main"><strong>${escapeHtml(t.name)}</strong><small>${escapeHtml(t.formula)} · ${t.entries.length} resultados</small></div><div class="directory-item-actions"><button data-table-roll="${t.id}" title="Rolar">⚄</button>${state.canManage?`<button data-table-secret="${t.id}" title="Rolar secreto">◐</button><button data-table-delete="${t.id}">×</button>`:''}</div></div>`).join('')||'<div class="empty-state">Nenhuma tabela.</div>';$$('[data-table-roll]').forEach(b=>b.onclick=()=>rollTable(Number(b.dataset.tableRoll),false));$$('[data-table-secret]').forEach(b=>b.onclick=()=>rollTable(Number(b.dataset.tableSecret),true));$$('[data-table-delete]').forEach(b=>b.onclick=()=>deleteResource(`/api/vtt/tables/${b.dataset.tableDelete}`,loadBootstrap));}
function renderDecks(){$("#deck-directory").innerHTML=state.decks.map(d=>`<div class="directory-item"><span class="directory-item-thumb">▤</span><div class="directory-item-main"><strong>${escapeHtml(d.name)}</strong><small>${d.cards.length} cartas · ${d.discard.length} descartadas</small></div><div class="directory-item-actions"><button data-deck-draw="${d.id}" title="Comprar">↑</button>${state.canManage?`<button data-deck-shuffle="${d.id}" title="Embaralhar">⟳</button><button data-deck-reset="${d.id}" title="Resetar">↺</button><button data-deck-delete="${d.id}">×</button>`:''}</div></div>`).join('')||'<div class="empty-state">Nenhum baralho.</div>';$$('[data-deck-draw]').forEach(b=>b.onclick=()=>deckAction(Number(b.dataset.deckDraw),'draw'));$$('[data-deck-shuffle]').forEach(b=>b.onclick=()=>deckAction(Number(b.dataset.deckShuffle),'shuffle'));$$('[data-deck-reset]').forEach(b=>b.onclick=()=>deckAction(Number(b.dataset.deckReset),'reset'));$$('[data-deck-delete]').forEach(b=>b.onclick=()=>deleteResource(`/api/vtt/decks/${b.dataset.deckDelete}`,loadBootstrap));}
function renderMedia(){const active=state.media.find(m=>m.is_active);const player=$("#active-media-player");if(player){if(!active){player.hidden=true;player.innerHTML='';if(state.playlistAudio){state.playlistAudio.pause();state.playlistAudio=null;state.playlistAudioId=null;}}else{player.hidden=false;const directAudio=active.media_type==='audio'&&/^https?:/i.test(active.url||'');player.innerHTML=`<strong>${escapeHtml(active.title)}</strong><small>${escapeHtml(active.category)} · ambiente ativo da mesa</small><div class="media-actions"><a class="mini-button" href="${escapeHtml(active.url)}" target="_blank" rel="noopener">Abrir mídia ↗</a>${directAudio?'<button class="mini-button" id="local-play-active" type="button">▶ Ouvir aqui</button>':''}</div>`;if(directAudio){const btn=$("#local-play-active");btn.onclick=()=>{if(state.playlistAudioId!==active.id){state.playlistAudio?.pause();state.playlistAudio=new Audio(active.url);state.playlistAudio.loop=true;state.playlistAudioId=active.id;}state.playlistAudio.volume=clamp(state.localVolumes.playlist,0,1);if(state.playlistAudio.paused){state.playlistAudio.play().catch(()=>toast('O navegador bloqueou o áudio automático. Clique novamente.'));btn.textContent='■ Pausar';}else{state.playlistAudio.pause();btn.textContent='▶ Ouvir aqui';}};}}}$("#media-directory").innerHTML=state.media.map(m=>`<div class="directory-item ${m.is_active?'active':''}"><span class="directory-item-thumb">♫</span><div class="directory-item-main"><strong>${escapeHtml(m.title)}</strong><small>${escapeHtml(m.category)} · ${escapeHtml(m.media_type)}</small></div><div class="directory-item-actions"><a href="${escapeHtml(m.url)}" target="_blank" rel="noopener" title="Abrir">↗</a>${state.canManage?`<button data-media-toggle="${m.id}" data-active="${m.is_active}">${m.is_active?'■':'▶'}</button>`:''}</div></div>`).join('')||'<div class="empty-state">Nenhuma mídia.</div>';$$('[data-media-toggle]').forEach(b=>b.onclick=()=>toggleMedia(Number(b.dataset.mediaToggle),b.dataset.active==='1'));}
function renderCutscenes(){const box=$("#cutscene-directory");if(!box)return;box.innerHTML=(state.cutscenes||[]).map(c=>`<div class="cutscene-card ${c.is_active?'active':''}"><strong>${escapeHtml(c.title)}</strong><small>${c.video_url?'Vídeo local':'Sem vídeo'}${c.is_active?` · ${escapeHtml(c.playback_state||'ativo')}`:''}</small><div class="row">${state.canManage?`<button class="mini-button" data-cut-launch="${c.id}">▶ Lançar cutscene</button>${c.is_active&&c.playback_state==='playing'?`<button class="mini-button" data-cut-pause="${c.id}">Ⅱ Pausar</button>`:''}${c.is_active&&c.playback_state==='paused'?`<button class="mini-button" data-cut-resume="${c.id}">▶ Retomar</button>`:''}${c.is_active?`<button class="danger-button" data-cut-end="${c.id}">Encerrar</button>`:''}<button class="mini-button" data-cut-delete="${c.id}">×</button>`:''}</div></div>`).join('')||'<div class="empty-state">Nenhuma cutscene preparada.</div>';$$('[data-cut-launch]',box).forEach(b=>b.onclick=()=>cutsceneAction(Number(b.dataset.cutLaunch),'launch'));$$('[data-cut-pause]',box).forEach(b=>b.onclick=()=>cutsceneAction(Number(b.dataset.cutPause),'pause'));$$('[data-cut-resume]',box).forEach(b=>b.onclick=()=>cutsceneAction(Number(b.dataset.cutResume),'resume'));$$('[data-cut-end]',box).forEach(b=>b.onclick=()=>cutsceneAction(Number(b.dataset.cutEnd),'end'));$$('[data-cut-delete]',box).forEach(b=>b.onclick=()=>deleteResource(`/api/cutscenes/${b.dataset.cutDelete}`,loadBootstrap));}

function renderCompendium(filter=""){const q=filter.toLowerCase();let last="";$("#compendium-directory").innerHTML=compendium.filter(x=>(x.name+x.group+x.text).toLowerCase().includes(q)).map(x=>{const h=x.group!==last?(last=x.group,`<div class="directory-folder">${escapeHtml(x.group)}</div>`):'';return `${h}<button class="directory-item" data-compendium="${escapeHtml(x.name)}"><span class="directory-item-thumb">⌘</span><span class="directory-item-main"><strong>${escapeHtml(x.name)}</strong><small>${escapeHtml(x.text)}</small></span></button>`}).join('');$$('[data-compendium]').forEach(b=>b.onclick=()=>{const x=compendium.find(c=>c.name===b.dataset.compendium);viewRecord(x.group,x.name,x.text);});}

function renderCombat(){$("#combat-list").innerHTML=state.encounters.map(e=>`<div class="settings-card"><div class="directory-header"><div><p class="eyebrow">${e.status==='active'?'Ativo':'Encerrado'}</p><h2>${escapeHtml(e.title)}</h2></div><span class="scene-chip muted">Rodada ${e.round}</span></div><div class="directory-list">${(e.participants||[]).map((p,index)=>{const obj=typeof p==='string'?{name:p,initiative:index+1}:p;return `<div class="directory-item"><span class="directory-item-thumb">${index+1}</span><div class="directory-item-main"><strong>${escapeHtml(obj.name||'Participante')}</strong><small>Iniciativa ${obj.initiative??'—'}${obj.defeated?' · derrotado':''}</small></div></div>`}).join('')}</div>${state.canManage&&e.status==='active'?`<div class="row" style="margin-top:.6rem"><button class="mini-button" data-next-round="${e.id}">Próxima rodada</button><button class="mini-button" data-finish-combat="${e.id}">Encerrar</button></div>`:''}</div>`).join('')||'<div class="empty-state">Nenhum encontro.</div>';$$('[data-next-round]').forEach(b=>b.onclick=async()=>{const e=state.encounters.find(x=>x.id===Number(b.dataset.nextRound));await api(`/api/conflicts/${e.id}`,{method:'PATCH',body:JSON.stringify({round:e.round+1,participants:e.participants})});await loadBootstrap();});$$('[data-finish-combat]').forEach(b=>b.onclick=async()=>{const e=state.encounters.find(x=>x.id===Number(b.dataset.finishCombat));await api(`/api/conflicts/${e.id}`,{method:'PATCH',body:JSON.stringify({status:'finished',round:e.round,participants:e.participants})});await loadBootstrap();});}

// ----- Chat -----
async function loadMessages(){const data=await api(`/api/chronicles/${chronicleId}/messages?after=${state.lastMessageId}`);if(data.messages.length){for(const m of data.messages){state.messages.push(m);state.lastMessageId=Math.max(state.lastMessageId,m.id);}if(state.messages.length>500)state.messages=state.messages.slice(-500);renderChat();}}
function renderChat(){const box=$("#chat-log");const filter=state.chatFilter;box.innerHTML=state.messages.filter(m=>filter==='all'||m.channel===filter).map(m=>`<article class="chat-message ${m.channel}"><header><strong>${escapeHtml(m.sender_name)}</strong><span>${m.channel==='whisper'?`privado${m.recipient_name?' → '+escapeHtml(m.recipient_name):''}`:m.channel} · ${timeLabel(m.created_at)}</span></header><p>${escapeHtml(m.content)}</p></article>`).join('')||'<div class="empty-state">A mesa ainda está silenciosa.</div>';box.scrollTop=box.scrollHeight;}
$("#chat-channel").onchange=()=>{$("#chat-recipient").hidden=$("#chat-channel").value!=="whisper";};$("#chat-form").onsubmit=async e=>{e.preventDefault();const content=$("#chat-input").value.trim();if(!content)return;await api(`/api/chronicles/${chronicleId}/messages`,{method:'POST',body:JSON.stringify({channel:$("#chat-channel").value,recipientId:$("#chat-channel").value==='whisper'?Number($("#chat-recipient").value):null,content})});$("#chat-input").value='';await loadMessages();};$$('[data-chat-filter]').forEach(b=>b.onclick=()=>{state.chatFilter=b.dataset.chatFilter;$$('[data-chat-filter]').forEach(x=>x.classList.toggle('active',x===b));renderChat();});
$("#export-chat").onclick=()=>{const text=state.messages.map(m=>`[${m.created_at}] ${m.sender_name}${m.recipient_name?` → ${m.recipient_name}`:''}: ${m.content}`).join('\n');const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`elysium-${state.chronicle.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-chat.txt`;a.click();URL.revokeObjectURL(a.href);};

// ----- Dialogs / CRUD -----
function openFormDialog({eyebrow="ELYSIUM",title,fields,onSubmit,submitLabel="Salvar"}){const dialog=$("#form-dialog"),form=$("#dynamic-form");$("#dialog-eyebrow").textContent=eyebrow;$("#dialog-title").textContent=title;$("#dialog-body").innerHTML=fields;$("#dialog-submit").textContent=submitLabel;const handler=async e=>{if(e.submitter?.value==='cancel')return; e.preventDefault();const fd=new FormData(form);try{await onSubmit(fd);form.removeEventListener('submit',handler);dialog.close();}catch{}};form.addEventListener('submit',handler);dialog.addEventListener('close',()=>form.removeEventListener('submit',handler),{once:true});dialog.showModal();}
function viewRecord(eyebrow,title,content){$("#viewer-eyebrow").textContent=eyebrow;$("#viewer-title").textContent=title;$("#viewer-body").innerHTML=`<p>${escapeHtml(content||'').replaceAll('\n','<br>')}</p>`;$("#viewer-dialog").showModal();}
$("#viewer-close").onclick=()=>$("#viewer-dialog").close();
async function deleteResource(path,after){if(!confirm('Excluir este registro?'))return;await api(path,{method:'DELETE'});await after();}

function sceneFields(scene={}){return `<label>Nome<input name="title" required value="${escapeHtml(scene.title||'')}"></label><label>Imagem de fundo<input name="imageFile" type="file" accept="image/*"><input name="imageUrl" type="hidden" value="${escapeHtml(scene.image_url||'')}"><small>${scene.image_url?'Imagem atual preservada se nenhum arquivo novo for escolhido.':'Escolha a imagem diretamente do seu PC.'}</small></label><label>Foreground / sobreposição<input name="foregroundFile" type="file" accept="image/*"><input name="foregroundUrl" type="hidden" value="${escapeHtml(scene.foreground_url||'')}"></label><label>Descrição<textarea name="description">${escapeHtml(scene.description||'')}</textarea></label><div class="field-grid three"><label>Largura<input name="width" type="number" value="${scene.width||1920}"></label><label>Altura<input name="height" type="number" value="${scene.height||1080}"></label><label>Grid<select name="gridType"><option value="square" ${scene.grid_type==='square'?'selected':''}>Quadrado</option><option value="hex-row" ${scene.grid_type==='hex-row'?'selected':''}>Hexagonal</option><option value="gridless" ${scene.grid_type==='gridless'?'selected':''}>Sem grid</option></select></label></div><div class="field-grid three"><label>Tamanho grid<input name="gridSize" type="number" value="${scene.grid_size||70}"></label><label>Distância/célula<input name="gridDistance" type="number" step=".1" value="${scene.grid_distance||1.5}"></label><label>Unidade<input name="gridUnits" value="${escapeHtml(scene.grid_units||'m')}"></label></div><div class="field-grid three"><label>Escuridão<input name="darkness" type="number" min="0" max="1" step=".05" value="${scene.darkness??.45}"></label><label>Clima<select name="weatherEffect"><option value="">Nenhum</option><option value="rain" ${scene.weather_effect==='rain'?'selected':''}>Chuva</option><option value="snow" ${scene.weather_effect==='snow'?'selected':''}>Neve</option><option value="ash" ${scene.weather_effect==='ash'?'selected':''}>Cinzas</option></select></label><label>Pasta<select name="folderId"><option value="">Sem pasta</option>${state.folders.map(f=>`<option value="${f.id}" ${scene.folder_id===f.id?'selected':''}>${escapeHtml(f.name)}</option>`).join('')}</select></label></div><label class="check-line"><input name="globalIllumination" type="checkbox" ${scene.global_illumination!==false&&scene.global_illumination!==0?'checked':''}> Iluminação global</label><label class="check-line"><input name="fogEnabled" type="checkbox" ${scene.fog_enabled?'checked':''}> Fog of War</label><label class="check-line"><input name="explorerEnabled" type="checkbox" ${scene.explorer_enabled?'checked':''}> Explorer Mode</label><label class="check-line"><input name="restrictMovement" type="checkbox" ${scene.restrict_movement!==false&&scene.restrict_movement!==0?'checked':''}> Restringir movimento por paredes</label><label class="check-line"><input name="navVisible" type="checkbox" ${scene.nav_visible!==false&&scene.nav_visible!==0?'checked':''}> Mostrar na navegação</label><label class="check-line"><input name="gmOnly" type="checkbox" ${scene.gm_only?'checked':''}> Somente Mestre</label>`;}
function sceneBody(fd){return {title:fd.get('title'),imageUrl:fd.get('imageUrl'),foregroundUrl:fd.get('foregroundUrl'),description:fd.get('description'),width:Number(fd.get('width')),height:Number(fd.get('height')),gridType:fd.get('gridType'),gridSize:Number(fd.get('gridSize')),gridDistance:Number(fd.get('gridDistance')),gridUnits:fd.get('gridUnits'),darkness:Number(fd.get('darkness')),weatherEffect:fd.get('weatherEffect'),folderId:fd.get('folderId')?Number(fd.get('folderId')):null,globalIllumination:fd.has('globalIllumination'),fogEnabled:fd.has('fogEnabled'),explorerEnabled:fd.has('explorerEnabled'),restrictMovement:fd.has('restrictMovement'),navVisible:fd.has('navVisible'),gmOnly:fd.has('gmOnly')};}
async function sceneBodyWithUploads(fd){const body=sceneBody(fd);const image=fd.get('imageFile'),foreground=fd.get('foregroundFile');if(image instanceof File&&image.size)body.imageUrl=await uploadFile(image,'image');if(foreground instanceof File&&foreground.size)body.foregroundUrl=await uploadFile(foreground,'image');return body;}
function newScene(){openFormDialog({eyebrow:'Scene',title:'Nova cena',fields:sceneFields(),onSubmit:async fd=>{const body=await sceneBodyWithUploads(fd);const d=await api(`/api/vtt/chronicles/${chronicleId}/scenes`,{method:'POST',body:JSON.stringify(body)});await loadBootstrap({keepScene:false});await openScene(d.id,{fit:true});}});}
function editScene(id){const s=state.scenes.find(x=>x.id===id);openFormDialog({eyebrow:'Scene Settings',title:s.title,fields:sceneFields(s)+`<div><button type="button" class="danger-button" id="dialog-delete-scene">Excluir cena</button></div>`,onSubmit:async fd=>{const body=await sceneBodyWithUploads(fd);await api(`/api/vtt/scenes/${id}`,{method:'PATCH',body:JSON.stringify(body)});await loadBootstrap();await openScene(id);}});setTimeout(()=>{$("#dialog-delete-scene").onclick=async()=>{if(!confirm(`Excluir a cena "${s.title}"?`))return;await api(`/api/vtt/scenes/${id}`,{method:'DELETE'});$("#form-dialog").close();await loadBootstrap({keepScene:false});};});}
async function activateScene(id){await api(`/api/vtt/scenes/${id}/activate`,{method:'POST'});await loadBootstrap();await openScene(id,{fit:true});toast('Cena ativada para a mesa.');}

function newItem(){openFormDialog({eyebrow:'Items',title:'Novo item',fields:`<label>Nome<input name="name" required></label><label>Tipo<input name="itemType" value="item"></label><label>Pasta<input name="folder"></label><label>Imagem<input name="imageFile" type="file" accept="image/*"></label><label>Descrição<textarea name="description"></textarea></label><label>Visibilidade<select name="visibility"><option value="all">Todos</option><option value="master">Somente Mestre</option></select></label>`,onSubmit:async fd=>{const imageUrl=fd.get('imageFile') instanceof File&&fd.get('imageFile').size?await uploadFile(fd.get('imageFile'),'image'):'';await api(`/api/vtt/chronicles/${chronicleId}/items`,{method:'POST',body:JSON.stringify({name:fd.get('name'),itemType:fd.get('itemType'),folder:fd.get('folder'),imageUrl,description:fd.get('description'),visibility:fd.get('visibility')})});await loadBootstrap();}});}
function newJournal(){openFormDialog({eyebrow:'Journal',title:'Novo registro / handout',fields:`<label>Título<input name="title" required></label><label>Tipo<select name="entryType"><option value="handout">Handout</option><option value="session">Sessão</option><option value="location">Local</option><option value="npc">NPC</option><option value="lore">Lore</option></select></label><label>Conteúdo<textarea name="content"></textarea></label><label>Visibilidade<select name="visibility"><option value="all">Jogadores</option><option value="master">Somente Mestre</option></select></label>`,onSubmit:async fd=>{await api(`/api/chronicles/${chronicleId}/diary`,{method:'POST',body:JSON.stringify(Object.fromEntries(fd))});await loadBootstrap();}});}
function newTable(){openFormDialog({eyebrow:'Rollable Table',title:'Nova tabela',fields:`<label>Nome<input name="name" required></label><label>Fórmula<input name="formula" value="1d10"></label><label>Resultados<textarea name="entries" placeholder="1-2 | Resultado A\n3-6 | Resultado B\n7-10 | Resultado C"></textarea></label>`,onSubmit:async fd=>{const entries=String(fd.get('entries')||'').split('\n').map(line=>{const [range,...rest]=line.split('|');if(!rest.length)return null;const [min,max]=range.trim().split('-').map(Number);return {min:min||1,max:max||min||1,text:rest.join('|').trim()};}).filter(Boolean);await api(`/api/vtt/chronicles/${chronicleId}/tables`,{method:'POST',body:JSON.stringify({name:fd.get('name'),formula:fd.get('formula'),entries})});await loadBootstrap();}});}
function newDeck(){openFormDialog({eyebrow:'Cards',title:'Novo baralho',fields:`<label>Nome<input name="name" required></label><label>Cartas<textarea name="cards" placeholder="Uma carta por linha"></textarea></label>`,onSubmit:async fd=>{const cards=String(fd.get('cards')||'').split('\n').map(x=>x.trim()).filter(Boolean);await api(`/api/vtt/chronicles/${chronicleId}/decks`,{method:'POST',body:JSON.stringify({name:fd.get('name'),cards})});await loadBootstrap();}});}
function newMedia(){openFormDialog({eyebrow:'Jukebox',title:'Adicionar mídia',fields:`<label>Título<input name="title" required></label><label>Categoria<input name="category" value="Ambiente"></label><label>URL<input name="url" required placeholder="YouTube ou arquivo de áudio"></label><label>Tipo<select name="mediaType"><option value="youtube">YouTube</option><option value="audio">Áudio</option><option value="video">Vídeo</option></select></label>`,onSubmit:async fd=>{await api(`/api/chronicles/${chronicleId}/media`,{method:'POST',body:JSON.stringify(Object.fromEntries(fd))});await loadBootstrap();}});}
function newCutscene(){openFormDialog({eyebrow:'Cutscene',title:'Nova cutscene',submitLabel:'Salvar cutscene',fields:`<label>Título<input name="title" required placeholder="A chegada do Príncipe"></label><label>Vídeo da cutscene<input name="videoFile" type="file" accept="video/mp4,video/webm" required><small>MP4 ou WebM enviado diretamente do seu PC.</small></label>`,onSubmit:async fd=>{const videoUrl=await uploadFile(fd.get('videoFile'),'video');await api(`/api/chronicles/${chronicleId}/cutscenes`,{method:'POST',body:JSON.stringify({title:fd.get('title'),videoUrl,steps:[]})});await loadBootstrap();openDirectory('cutscenes');}});}
async function cutsceneAction(id,action){await api(`/api/cutscenes/${id}/${action}`,{method:'POST'});await loadBootstrap();await syncLive();}

const HOTBAR_PAGES=5;
function newMacro(){const base=state.hotbarPage*10;openFormDialog({eyebrow:'Macro',title:'Nova macro',fields:`<label>Nome<input name="name" required></label><label>Comando<textarea name="command" placeholder="/roll 6 2\n/say A noite começa...\n/table 1"></textarea></label><div class="field-grid two"><label>Slot<select name="slot"><option value="">Sem slot</option>${Array.from({length:10},(_,i)=>`<option value="${base+i}">Página ${state.hotbarPage+1} · ${i===9?0:i+1}</option>`).join('')}</select></label><label>Visibilidade<select name="visibility"><option value="private">Privada</option><option value="all">Compartilhada</option></select></label></div>`,onSubmit:async fd=>{await api(`/api/vtt/chronicles/${chronicleId}/macros`,{method:'POST',body:JSON.stringify({name:fd.get('name'),command:fd.get('command'),slot:fd.get('slot')===''?null:Number(fd.get('slot')),visibility:fd.get('visibility')})});await loadBootstrap();}});}
function changeHotbarPage(delta){state.hotbarPage=(state.hotbarPage+delta+HOTBAR_PAGES)%HOTBAR_PAGES;renderHotbar();}

async function rollTable(id,secret){const d=await api(`/api/vtt/tables/${id}/roll`,{method:'POST',body:JSON.stringify({secret})});viewRecord(secret?'Tabela · secreta':'Tabela','Resultado',`${d.result?.text??d.result?.label??'Sem resultado'}\nRolagem: ${d.roll.formula} = ${d.roll.total}`);if(!secret)await loadMessages();}
async function deckAction(id,action){const d=await api(`/api/vtt/decks/${id}/${action}`,{method:'POST'});if(action==='draw')viewRecord('Cards','Carta comprada',typeof d.card==='string'?d.card:JSON.stringify(d.card,null,2));await loadBootstrap();}
async function toggleMedia(id,active){await api(`/api/media/${id}/${active?'deactivate':'activate'}`,{method:'POST'});await loadBootstrap();}

function newEncounter(){const tokens=state.objects.tokens.filter(t=>state.selectedTokens.size?state.selectedTokens.has(t.id):true);if(!tokens.length){toast('Adicione ou selecione tokens na cena.');return;}const participants=tokens.map((t,i)=>({tokenId:t.id,name:t.name,initiative:Math.floor(Math.random()*10)+1,defeated:false})).sort((a,b)=>b.initiative-a.initiative);openFormDialog({eyebrow:'Combat Tracker',title:'Novo encontro',fields:`<label>Título<input name="title" value="Conflito"></label><div class="settings-card"><p>${participants.map(p=>`${escapeHtml(p.name)} · iniciativa ${p.initiative}`).join('<br>')}</p></div>`,onSubmit:async fd=>{await api(`/api/chronicles/${chronicleId}/conflicts`,{method:'POST',body:JSON.stringify({title:fd.get('title'),mode:'detailed',participants})});await loadBootstrap();}});}

// ----- Dados / macros -----
function fillDiceCharacters(){$("#dice-character").innerHTML=`<option value="">Rolagem livre</option>${state.characters.filter(c=>state.canManage||c.user_id===state.me.id).map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}`;}
$("#open-dice").onclick=()=>$("#dice-dialog").showModal();$("#dice-form").addEventListener('submit',async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const body={characterId:$("#dice-character").value?Number($("#dice-character").value):null,pool:Number($("#dice-pool").value)||1,hunger:Number($("#dice-hunger").value)||0,modifier:Number($("#dice-modifier").value)||0,difficulty:$("#dice-difficulty").value?Number($("#dice-difficulty").value):null,secret:$("#dice-secret").checked};const d=await api(`/api/vtt/chronicles/${chronicleId}/rolls`,{method:'POST',body:JSON.stringify(body)});$("#dice-dialog").close();animateDice(d.roll);state.lastRollId=Math.max(state.lastRollId,Number(d.roll.id)||0);state.rolls.unshift(d.roll);if(!body.secret)await loadMessages();});
function animateDice(roll){const box=$("#dice-overlay"),normal=roll.normalDice||roll.normal_dice||[],hunger=roll.hungerDice||roll.hunger_dice||[],type=roll.resultType||roll.result_type;box.innerHTML=`${normal.map(d=>`<span class="die">${d}</span>`).join('')}${hunger.map(d=>`<span class="die hunger">${d}</span>`).join('')}<div class="dice-result-card"><span>RESULTADO DA ROLAGEM</span><strong>${roll.successes} ${Number(roll.successes)===1?'SUCESSO':'SUCESSOS'}</strong><em>${resultLabel(type)}</em></div>`;box.hidden=false;clearTimeout(animateDice.timer);animateDice.timer=setTimeout(()=>box.hidden=true,4200);}
function renderHotbar(){const box=$("#hotbar-slots");const base=state.hotbarPage*10;const bySlot=new Map(state.macros.filter(m=>m.slot!=null).map(m=>[Number(m.slot),m]));box.innerHTML=Array.from({length:10},(_,slot)=>{const absolute=base+slot,m=bySlot.get(absolute);return `<button class="hotbar-slot ${m?'filled':''}" data-hotbar-slot="${absolute}" ${m?`data-macro-id="${m.id}" title="${escapeHtml(m.command)}"`:''}><em>${slot===9?0:slot+1}</em><b>${m?escapeHtml(m.icon||'◆'):'·'}</b><small>${m?escapeHtml(m.name):'Vazio'}</small></button>`}).join('');$("#hotbar-prev").title=`Página anterior · atual ${state.hotbarPage+1}/${HOTBAR_PAGES}`;$("#hotbar-next").title=`Próxima página · atual ${state.hotbarPage+1}/${HOTBAR_PAGES}`;$$('[data-macro-id]',box).forEach(b=>b.onclick=()=>runMacro(state.macros.find(m=>m.id===Number(b.dataset.macroId))));$$('.hotbar-slot:not([data-macro-id])',box).forEach(b=>b.ondblclick=newMacro);}
async function runMacro(macro){const command=macro.command.trim();if(command.startsWith('/roll ')){const [,pool='1',hunger='0']=command.split(/\s+/);const d=await api(`/api/vtt/chronicles/${chronicleId}/rolls`,{method:'POST',body:JSON.stringify({pool:Number(pool)||1,hunger:Number(hunger)||0})});animateDice(d.roll);state.lastRollId=Math.max(state.lastRollId,Number(d.roll.id)||0);state.rolls.unshift(d.roll);await loadMessages();return;}if(command.startsWith('/say ')){await api(`/api/chronicles/${chronicleId}/messages`,{method:'POST',body:JSON.stringify({channel:'general',content:command.slice(5)})});await loadMessages();return;}if(command.startsWith('/table ')){await rollTable(Number(command.split(/\s+/)[1]),false);return;}toast(`Macro: ${macro.name}`);}

// ----- Settings -----
function renderSettings(){const pane=$("#settings-pane");if(!pane)return;pane.innerHTML=`<div class="settings-card"><h3>Usuário</h3><p>${escapeHtml(state.me?.name||'')} · ${escapeHtml(roleLabel(state.role))}</p><div class="row"><button class="mini-button" id="settings-center">Centralizar cena</button>${state.canManage?'<button class="mini-button" id="settings-player-view">Visão do jogador</button>':''}</div></div>${state.canManage?`<div class="settings-card"><h3>Diretor da mesa</h3><p>Controle de cena, pausa, iluminação, fog e permissões.</p><div class="row"><button class="mini-button" id="settings-scene">Configurar cena</button><button class="mini-button" id="settings-pause">${state.world.paused?'Retomar':'Pausar'}</button></div></div>`:''}<div class="settings-card"><h3>Áudio e vídeo</h3><p>Playlists e sons funcionam no navegador. Voz/vídeo P2P não é iniciado automaticamente porque acesso via Radmin em HTTP pode bloquear câmera e microfone; HTTPS é recomendado para WebRTC.</p><div class="row"><button class="mini-button" id="test-media">Testar câmera/microfone</button></div></div><div class="settings-card"><h3>Ajuda</h3><p>Abra o tutorial completo da Sala da Crônica quando quiser.</p><div class="row"><button class="mini-button" id="settings-tutorial">Abrir tutorial</button></div></div><div class="settings-card"><h3>Atalhos</h3><p>V Selecionar · H Mover · R Medir · P Ping · D Lápis · E Borracha · Delete excluir · 1–0 hotbar · Espaço arrastar câmera.</p></div>`;$("#settings-center").onclick=fitScene;const pv=$("#settings-player-view");if(pv)pv.onclick=togglePlayerView;const sc=$("#settings-scene");if(sc)sc.onclick=()=>state.scene&&editScene(state.scene.id);const pause=$("#settings-pause");if(pause)pause.onclick=togglePause;$("#test-media").onclick=testMedia;const tut=$("#settings-tutorial");if(tut)tut.onclick=showTutorial;}
async function testMedia(){if(!navigator.mediaDevices?.getUserMedia){toast('Câmera/microfone indisponíveis neste contexto.');return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:true});const video=document.createElement('video');video.autoplay=true;video.muted=true;video.srcObject=stream;$("#viewer-eyebrow").textContent='Teste local';$("#viewer-title").textContent='Câmera e microfone';$("#viewer-body").innerHTML='';$("#viewer-body").append(video);video.style.width='100%';$("#viewer-dialog").showModal();$("#viewer-dialog").addEventListener('close',()=>stream.getTracks().forEach(t=>t.stop()),{once:true});}catch{toast('O navegador bloqueou câmera/microfone. Em rede, use HTTPS para comunicação WebRTC.');}}

async function togglePause(){if(!state.canManage)return;const paused=!state.world.paused;await api(`/api/vtt/chronicles/${chronicleId}/pause`,{method:'POST',body:JSON.stringify({paused})});state.world.paused=paused;applyPause();renderSettings();}
function applyPause(){$("#pause-overlay").hidden=!state.world.paused;$("#pause-game").classList.toggle('active',state.world.paused);$("#pause-game").title=state.world.paused?'Retomar mesa':'Pausar mesa';}
function togglePlayerView(){if(!state.canManage)return;state.playerView=!state.playerView;$("#player-view").classList.toggle('active',state.playerView);updateMasterVisibility();renderWalls();renderGmMarkers();renderLighting();renderFog();renderSettings();toast(state.playerView?'Simulando visão de jogador.':'Visão do Mestre restaurada.');}

// ----- Controles gerais -----
$("#open-tutorial").onclick=showTutorial;$("#add-scene").onclick=newScene;$("#empty-add-scene").onclick=newScene;$("#new-scene-side").onclick=newScene;$("#pause-game").onclick=togglePause;$("#player-view").onclick=togglePlayerView;$("#zoom-in").onclick=()=>{const r=viewport.getBoundingClientRect();zoomAt(1,r.left+r.width/2,r.top+r.height/2)};$("#zoom-out").onclick=()=>{const r=viewport.getBoundingClientRect();zoomAt(-1,r.left+r.width/2,r.top+r.height/2)};$("#zoom-fit").onclick=fitScene;$("#center-scene").onclick=fitScene;$("#toggle-sidebar").onclick=()=>$("#directory-sidebar").classList.toggle('closed');$("#close-inspector").onclick=()=>{state.selected=null;renderInspector();};
$("#new-item").onclick=newItem;$("#new-journal").onclick=newJournal;$("#new-table").onclick=newTable;$("#new-deck").onclick=newDeck;$("#new-media").onclick=newMedia;$("#new-cutscene").onclick=newCutscene;$("#new-macro").onclick=newMacro;$("#new-encounter").onclick=newEncounter;$("#hotbar-prev").onclick=()=>changeHotbarPage(-1);$("#hotbar-next").onclick=()=>changeHotbarPage(1);
$("#new-scene-folder").onclick=()=>openFormDialog({eyebrow:'Scene Directory',title:'Nova pasta',fields:`<label>Nome<input name="name" required></label>`,onSubmit:async fd=>{await api(`/api/vtt/chronicles/${chronicleId}/scene-folders`,{method:'POST',body:JSON.stringify({name:fd.get('name')})});await loadBootstrap();}});
$("#scene-search").oninput=e=>renderSceneDirectory(e.target.value);$("#actor-search").oninput=e=>renderActors(e.target.value);$("#item-search").oninput=e=>renderItems(e.target.value);$("#journal-search").oninput=e=>renderJournal(e.target.value);$("#compendium-search").oninput=e=>renderCompendium(e.target.value);
$("#playlist-volume").value=state.localVolumes.playlist;$("#ambient-volume").value=state.localVolumes.ambient;$("#interface-volume").value=state.localVolumes.interface;$("#playlist-volume").oninput=e=>{state.localVolumes.playlist=Number(e.target.value);localStorage.setItem('elysium.vtt.volume.playlist',e.target.value);if(state.playlistAudio)state.playlistAudio.volume=state.localVolumes.playlist};$("#ambient-volume").oninput=e=>{state.localVolumes.ambient=Number(e.target.value);localStorage.setItem('elysium.vtt.volume.ambient',e.target.value);updateAmbientSounds()};$("#interface-volume").oninput=e=>{state.localVolumes.interface=Number(e.target.value);localStorage.setItem('elysium.vtt.volume.interface',e.target.value)};
document.addEventListener('click',e=>{if(!$("#context-menu").contains(e.target))$("#context-menu").hidden=true;});
window.addEventListener('resize',()=>{if(state.scene)fitScene();});
window.addEventListener('keydown',async e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='Delete'&&state.selected&&state.canManage){await deleteSelected();return;}if(/^\d$/.test(e.key)){const localSlot=e.key==='0'?9:Number(e.key)-1,slot=state.hotbarPage*10+localSlot;const m=state.macros.find(x=>Number(x.slot)===slot);if(m){e.preventDefault();runMacro(m);}return;}const map={v:'select',h:'pan',r:'measure',p:'ping',d:'draw',e:'erase'};if(map[e.key.toLowerCase()])setTool(map[e.key.toLowerCase()]);if(e.code==='Space'){e.preventDefault();state.previousTool=state.tool;setTool('pan');}});window.addEventListener('keyup',e=>{if(e.code==='Space'&&state.previousTool){setTool(state.previousTool);state.previousTool=null;}});

function renderRemoteCursors(){const layer=$("#cursor-layer");layer.innerHTML='';if(!state.scene)return;for(const m of state.members.filter(x=>x.is_online&&x.id!==state.me.id&&x.scene_id===state.scene.id&&x.cursor_x!=null)){const el=document.createElement('div');el.className='remote-cursor';el.style.left=`${m.cursor_x}px`;el.style.top=`${m.cursor_y}px`;el.innerHTML=`↖<span>${escapeHtml(m.name)}</span>`;layer.append(el);}}
async function heartbeat(){try{await api(`/api/vtt/chronicles/${chronicleId}/presence`,{method:'POST',body:JSON.stringify({sceneId:state.scene?.id??null,cursorX:state.cursor.x,cursorY:state.cursor.y})});}catch{}}
async function poll(){try{if(state.scene){const globalGen=state.fogGeneration,explorerGen=state.explorerGeneration;const d=await api(`/api/vtt/scenes/${state.scene.id}`);state.scene=d.scene;state.objects=d.objects;mergeIncomingFog(d.fog,globalGen,explorerGen);state.pings=d.pings;renderScene();renderPings();updateAmbientSounds();}await loadMessages();}catch{}}
async function refreshBootstrapLight(){try{const d=await api(`/api/vtt/chronicles/${chronicleId}/bootstrap`);state.members=d.members;state.scenes=d.scenes;state.media=d.media;state.cutscenes=d.cutscenes||[];state.encounters=d.encounters;state.world=d.world;state.rolls=d.rolls;state.items=d.items;state.journals=d.journals;state.tables=d.tables;state.decks=d.decks;state.macros=d.macros;renderOnline();renderSceneNavigation();renderDirectories();renderHotbar();renderSettings();renderRemoteCursors();applyPause();}catch{}}

function showTutorial(){localStorage.setItem('elysium.vtt.tutorial.seen','1');$("#viewer-eyebrow").textContent='Tutorial';$("#viewer-title").textContent='Como usar a Sala da Crônica';$("#viewer-body").innerHTML=`<div class="tutorial-grid"><div class="tutorial-step"><b>1. Cenas</b><p>O Mestre cria a cena e escolhe a imagem diretamente do PC. Use a barra superior para trocar ou ativar cenas.</p></div><div class="tutorial-step"><b>2. Navegação</b><p>Selecionar escolhe objetos. Mover arrasta a câmera. Roda do mouse controla o zoom. Ajustar enquadra todo o mapa.</p></div><div class="tutorial-step"><b>3. Lápis e Borracha</b><p>Jogadores e Mestre podem desenhar. A borracha apaga suas próprias marcações; o Mestre apaga qualquer objeto e pode limpar as marcações da cena.</p></div><div class="tutorial-step"><b>4. Tokens e paredes</b><p>O Mestre posiciona tokens, tiles, paredes, portas, luzes, sons, notas e regiões. Paredes podem bloquear movimento e visão; portas abertas deixam a visão passar.</p></div><div class="tutorial-step"><b>5. Fog of War</b><p>Na ferramenta Fog, use Revelar para abrir uma área e Ocultar para cobri-la novamente. Resetar revelado limpa apenas as aberturas manuais; Limpar Explorer apaga o histórico explorado de todos. Explorer Mode memoriza somente o que a visão real do token alcançou.</p></div><div class="tutorial-step"><b>6. Rolagens V5</b><p>Abra Dados no chat. Os d10 aparecem em destaque no centro da tela para toda a mesa, enquanto o histórico continua no chat.</p></div><div class="tutorial-step"><b>7. Cutscenes</b><p>No diretório ▶, envie MP4/WebM do PC e clique em Lançar Cutscene. O vídeo substitui o cenário. Pausar devolve o mapa; Retomar continua do ponto salvo.</p></div><div class="tutorial-step"><b>8. Chat e diretórios</b><p>Use as abas à direita para chat, combate, cenas, atores, itens, diário, tabelas, cartas, música, cutscenes e configurações.</p></div><div class="tutorial-step"><b>9. Atalhos</b><p>V Selecionar · H Mover · R Medir · P Ping · D Lápis · E Borracha · Espaço para mover temporariamente a câmera.</p></div></div>`;$("#viewer-dialog").showModal();}

async function syncLive(){try{const live=await api(`/api/chronicles/${chronicleId}/live`);if(live.recentRoll&&Number(live.recentRoll.id)>state.lastRollId){state.lastRollId=Number(live.recentRoll.id);animateDice(live.recentRoll);}syncCutscene(live.cutscene);}catch{}}
function syncCutscene(c){const overlay=$("#cutscene-overlay"),video=$("#cutscene-video"),fallback=$("#cutscene-play-fallback");if(!c||c.playbackState==='stopped'){fallback.hidden=true;if(!overlay.hidden)overlay.hidden=true;if(!video.paused)video.pause();state.activeCutsceneId=null;return;}if(c.playbackState==='paused'){fallback.hidden=true;if(!video.paused)video.pause();overlay.hidden=true;state.activeCutsceneId=c.id;return;}const changed=state.activeCutsceneId!==c.id||video.dataset.src!==c.video_url;if(changed){video.src=c.video_url||'';video.dataset.src=c.video_url||'';state.activeCutsceneId=c.id;}$("#cutscene-active-title").textContent=c.title||'Cutscene';overlay.hidden=false;const target=Math.max(0,Number(c.playbackPosition||0));if(changed||Math.abs((video.currentTime||0)-target)>2.5){try{video.currentTime=target;}catch{}}video.play().then(()=>{fallback.hidden=true;}).catch(()=>{fallback.hidden=false;});}
$("#cutscene-play-fallback").onclick=()=>{$("#cutscene-video").play().then(()=>$("#cutscene-play-fallback").hidden=true).catch(()=>{});};$("#cutscene-pause").onclick=()=>state.activeCutsceneId&&cutsceneAction(state.activeCutsceneId,'pause');$("#cutscene-end").onclick=()=>state.activeCutsceneId&&cutsceneAction(state.activeCutsceneId,'end');$("#cutscene-video").addEventListener('ended',()=>{if(state.canManage&&state.activeCutsceneId)cutsceneAction(state.activeCutsceneId,'end');});

async function init(){await loadBootstrap({keepScene:false});await loadMessages();setTool('select');renderCompendium();fitScene();heartbeat();await syncLive();if(!localStorage.getItem('elysium.vtt.tutorial.seen'))setTimeout(showTutorial,700);setInterval(heartbeat,5000);setInterval(poll,2200);setInterval(syncLive,1500);setInterval(refreshBootstrapLight,6000);}
init();
